def validate_interval(interval):
    """Return the interval as a (start, end) tuple, raising on bad input."""
    start, end = interval
    if start > end:
        raise ValueError(f"interval start {start} exceeds its end {end}")
    return (start, end)


def intersect_intervals(i1, i2):
    """Return the overlapping part of two intervals, or None if they do not overlap."""
    start1, end1 = validate_interval(i1)
    start2, end2 = validate_interval(i2)
    start = max(start1, start2)
    end = min(end1, end2)
    if start < end:
        return (start, end)
    return None


def merge_intervals(i1, i2):
    """Return the smallest interval containing both inputs."""
    start1, end1 = validate_interval(i1)
    start2, end2 = validate_interval(i2)
    start = min(start1, start2)
    end = max(end1, end2)
    return (start, end)


def intersect_all(intervals):
    """Fold the intersection over a sequence of intervals."""
    current = validate_interval(intervals[0])
    for interval in intervals[1:]:
        current = intersect_intervals(current, interval)
        if current is None:
            return None
    return current


def merge_all(intervals):
    """Fold the bounding merge over a sequence of intervals."""
    current = validate_interval(intervals[0])
    for interval in intervals[1:]:
        current = merge_intervals(current, interval)
    return current


def duration(interval):
    """Length of an interval, zero for an empty (None) one."""
    if interval is None:
        return 0
    start, end = interval
    return end - start


def format_interval(interval):
    """Human readable form of an interval or of an empty result."""
    if interval is None:
        return "<empty>"
    return f"[{interval[0]}, {interval[1]})"


def report(intervals):
    """Build a one line summary of the overlap and the span of a group."""
    overlap = intersect_all(intervals)
    span = merge_all(intervals)
    parts = [
        "overlap=" + format_interval(overlap),
        "span=" + format_interval(span),
        "overlap_len={}".format(duration(overlap)),
        "span_len={}".format(duration(span)),
    ]
    return " | ".join(parts)


if __name__ == "__main__":
    i_a = (10, 20)
    i_b = (15, 25)
    overlap = intersect_intervals(i_a, i_b)
    print(overlap)
    print(merge_intervals(i_a, i_b))
    print(report([i_a, i_b]))
    late = (40, 50)
    print(report([i_a, late]))

