DEFAULT_FALLBACK = False

TRUTHY = (
    "true",
    "yes",
    "on",
)

FALSEY = (
    "false",
    "no",
    "off",
)


def parse_line(line, fallback):
    """Split a configuration line on '=' and return a (key, value) tuple."""
    try:
        key, value = line.split("=")
    except ValueError:
        return (line, fallback)
    return (key.strip(), value.strip())


def apply_setting(config_dict, pair_tuple):
    """Unpack a (key, value) tuple and store it in the dictionary."""
    key, value = pair_tuple
    config_dict[key] = value
    return config_dict


def get_setting(config_dict, key):
    """Return the stored value for key."""
    return config_dict[key]


def coerce_value(value):
    """Turn a raw configuration string into a bool, an int or the string."""
    if not isinstance(value, str):
        return value
    lowered = value.lower()
    if lowered in TRUTHY:
        return True
    if lowered in FALSEY:
        return False
    try:
        return int(value)
    except ValueError:
        return value


def load_lines(config_dict, lines):
    """Parse every line and apply the resulting pair to the dictionary."""
    for line in lines:
        pair = parse_line(line, DEFAULT_FALLBACK)
        apply_setting(config_dict, pair)
    return config_dict


def format_report(config_dict, keys):
    """Build a readable listing of the requested keys and coerced values."""
    rows = []
    for key in keys:
        raw = get_setting(config_dict, key)
        rows.append("{0:>14} : {1!r}".format(key, coerce_value(raw)))
    return "\n".join(rows)


def main():
    config = {}
    pair = parse_line("port=8080", False)
    apply_setting(config, pair)
    print(config)

    extra_lines = [
        "host=localhost",
        "debug=true",
        "retries=3",
        "malformed-line",
    ]
    load_lines(config, extra_lines)
    print(format_report(config, sorted(config)))
    port = coerce_value(get_setting(config, "port"))
    print("port as int:", port)


if __name__ == "__main__":
    main()

