HEADER = (
    "PATH",
    "EXT",
    "DIR",
)

DEFAULT_PATHS = (
    "/var/log/system.log",
    "/etc/hosts",
    "notes",
    "archive/data.tar.gz",
    "/tmp/",
)


def split_path(path):
    directory, filename = os.path.split(path)
    name, extension = os.path.splitext(filename)
    return directory, extension


def join_custom(dir_path, filename):
    return os.path.join(dir_path, filename)


def get_fallback_ext(path, default_ext):
    _directory, extension = split_path(path)
    if extension:
        return path, extension
    return path, default_ext


def describe(path, default_ext):
    resolved = get_fallback_ext(path, default_ext)
    directory = split_path(resolved[0])[0]
    return {
        "path": resolved[0],
        "ext": resolved[1],
        "dir": directory or ".",
    }


def format_row(values, width):
    return "{0:<{w}} {1:<10} {2}".format(*values, w=width)


def build_report(paths, default_ext):
    records = [describe(p, default_ext) for p in paths]
    width = max(len(r["path"]) for r in records)
    header = format_row(HEADER, width)
    lines = [header]
    lines.append("-" * len(header))
    for record in records:
        row = [record["path"], record["ext"]]
        row.append(record["dir"])
        lines.append(format_row(row, width))
    return "\n".join(lines)


def group_by_ext(paths, default_ext):
    groups = {}
    for path in paths:
        extension = get_fallback_ext(path, default_ext)[1]
        groups.setdefault(extension, []).append(path)
    return groups


