def merge_dicts(dict_a, dict_b):
    for key, value in dict_b.items():
        dict_a[key] = value
    return dict_a


def safe_get_list(target_dict, key):
    return target_dict.get(key, [])


def clone_dict(source_dict, default_val):
    cloned = {}
    for key in source_dict:
        cloned[key] = default_val
    return cloned


def append_pair(target_dict, pair):
    key, value = pair
    items = safe_get_list(target_dict, key)
    items.append(value)
    target_dict[key] = items
    return target_dict


def group_by_parity(numbers):
    groups = {}
    for number in numbers:
        label = "even" if number % 2 == 0 else "odd"
        pair = (label, number)
        append_pair(groups, pair)
    return groups


def build_registry(roles, names):
    registry = {}
    for pair in zip(roles, names):
        append_pair(registry, pair)
    return registry


def format_dict(title, data):
    lines = ["{}:".format(title)]
    for key in sorted(data, key=str):
        lines.append("  {} -> {}".format(key, data[key]))
    return "\n".join(lines)


def main():
    d1 = dict(a=1, b=2)
    d2 = dict(c=3, d=4)
    merged = merge_dicts(d1, d2)
    print(merged)

    print(format_dict("Merged", merged))
    reset = clone_dict(merged, 0)
    print(format_dict("Reset", reset))

