def get_dimensions(matrix, default_cols):
    rows = len(matrix)
    if rows == 0:
        return (0, default_cols)
    widths = sorted({len(row) for row in matrix})
    if len(widths) > 1:
        raise ValueError("ragged row widths: {}".format(widths))
    return (rows, widths[0])


def create_empty(rows, cols):
    if rows < 0 or cols < 0:
        raise ValueError("negative size: {}x{}".format(rows, cols))
    return [[0] * cols for _ in range(rows)]


def flatten_matrix(matrix, dims_tuple):
    rows, cols = dims_tuple
    flat = []
    for r in range(rows):
        for c in range(cols):
            flat.append(matrix[r][c])
    return flat


def transpose_dimensions(dims_tuple):
    rows, cols = dims_tuple
    return (cols, rows)


def transpose(matrix, dims_tuple):
    rows, cols = dims_tuple
    result = create_empty(cols, rows)
    for r in range(rows):
        for c in range(cols):
            result[c][r] = matrix[r][c]
    return result


def fill_from_flat(values, dims_tuple):
    rows, cols = dims_tuple
    expected = rows * cols
    if len(values) != expected:
        raise ValueError("expected {} values but got {}".format(expected, len(values)))
    matrix = create_empty(rows, cols)
    for index, value in enumerate(values):
        matrix[index // cols][index % cols] = value
    return matrix


def format_matrix(matrix, dims_tuple):
    rows, cols = dims_tuple
    lines = []
    for r in range(rows):
        cells = ["{:>4}".format(matrix[r][c]) for c in range(cols)]
        lines.append(" ".join(cells))
    return "\n".join(lines)


def describe(label,
             matrix,
             dims_tuple):
    flat = flatten_matrix(matrix, dims_tuple)
    print("{} dims: {}".format(label, dims_tuple))
    print("{} flat: {}".format(label, flat))
    print(format_matrix(matrix, dims_tuple))


def main():
    blank = create_empty(2, 3)
    blank_dims = get_dimensions(blank, 3)
    print("blank dims:", blank_dims)
    print("transposed dims:", transpose_dimensions(blank_dims))
    values = list(range(1, 7))
    data = fill_from_flat(values, blank_dims)
    describe("data",
             data,
             blank_dims)
    flipped = transpose(data, blank_dims)
    describe("flipped",
             flipped,
             transpose_dimensions(blank_dims))


if __name__ == "__main__":
    main()

