import math

NUMBER_TYPES = (int, float)


def base_area(radius):
    if radius < 0:
        raise ValueError("radius must be non-negative")
    return math.pi * radius ** 2


def lateral_area(radius, height):
    if min(radius, height) < 0:
        raise ValueError("radius and height must be non-negative")
    return 2 * math.pi * radius * height


def total_surface_area(radius, height):
    return 2 * base_area(radius) + lateral_area(radius, height)


def volume(radius, height):
    if height < 0:
        raise ValueError("height must be non-negative")
    return base_area(radius) * height


def parse_cylinder(entry):
    try:
        radius, height = entry
    except (TypeError, ValueError):
        raise ValueError(f"each cylinder needs exactly two numbers, got {entry!r}")
    for value in (radius, height):
        if not isinstance(value, NUMBER_TYPES):
            raise TypeError(f"radius and height must be numeric, got {entry!r}")
    return float(radius), float(height)


def metrics(cylinders):
    results = []
    for entry in cylinders:
        radius, height = parse_cylinder(entry)
        exact_area = total_surface_area(radius, height)
        exact_volume = volume(radius, height)
        area = round(exact_area, 2)
        vol = round(exact_volume, 2)
        results.append((area, vol))
    return results


def format_report(cylinders, computed):
    columns = (
        "radius",
        "height",
        "surface",
        "volume",
    )
    header = "{:>8} {:>8} {:>12} {:>12}".format(*columns)
    lines = [header, "-" * len(header)]
    for index, values in enumerate(computed):
        radius, height = parse_cylinder(cylinders[index])
        area, vol = values
        lines.append("{:>8.2f} {:>8.2f} {:>12.2f} {:>12.2f}".format(
            radius,
            height,
            area,
            vol,
        ))
    return "\n".join(lines)


def totals(computed):
    area_sum = sum(area for area, _ in computed)
    volume_sum = sum(vol for _, vol in computed)
    rounded_area = round(area_sum, 2)
    rounded_volume = round(volume_sum, 2)
    return rounded_area, rounded_volume


def main():
    batch = [
        (1, 2),
        (2.5, 4),
        (0.75, 10),
        (3, 3),
    ]
    computed = metrics(batch)
    print(format_report(batch, computed))
    area_sum, volume_sum = totals(computed)
    print("-" * 44)
    print("{:>30.2f} {:>12.2f}".format(area_sum, volume_sum))


if __name__ == "__main__":
    main()

