    return frequency * 2.0 * math.pi


def validate(speed,frequency):
    if not isinstance(speed,NUMERIC):
        raise TypeError("speed must be numeric: {!r}".format(speed))
    if not isinstance(frequency,NUMERIC):
        raise TypeError("frequency must be numeric: {!r}".format(frequency))
    if speed <= 0:
        raise ValueError("speed must be positive: {}".format(speed))
    if frequency <= 0:
        raise ValueError("frequency must be positive: {}".format(frequency))


def waves(properties):
    results = []
    for speed,frequency in properties:
        validate(speed,frequency)
        length = wavelength(speed,frequency)
        results.append((length,angular_frequency(frequency)))
    return results


def describe(speed,frequency):
    record = {}
    record["speed"] = speed
    record["frequency"] = frequency
    record["wavelength"] = wavelength(speed,frequency)
    record["period"] = period(frequency)
    record["angular_frequency"] = angular_frequency(frequency)
    return record


FIELDS = (
    "speed",
    "frequency",
    "wavelength",
    "period",
    "angular_frequency",
)

HEADERS = (
    "v (m/s)",
    "f (Hz)",
    "lambda (m)",
    "T (s)",
    "omega (rad/s)",
)


def header_row():
    cells = ["{:>14}".format(title) for title in HEADERS]
    return " ".join(cells)


def format_row(record):
    cells = ["{:>14.4f}".format(record[field]) for field in FIELDS]
    return " ".join(cells)


def report(properties):
    lines = [header_row()]
    lines.append("-" * (15 * len(FIELDS) - 1))
    for speed,frequency in properties:
        validate(speed,frequency)
        lines.append(format_row(describe(speed,frequency)))
    return "\n".join(lines)


def main():
    samples = [
        (300,50),
        (340,440),
        (1500,2.5),
        (3.0e8,1.0e6),
    ]
    print(report(samples))
    for length,omega in waves(samples):
        print("lambda={:.2f} m omega={:.2f} rad/s".format(length,omega))


if __name__ == "__main__":
    main()

