def combined_amplitude(first, second):
    amp_a, freq_a = first
    amp_b, freq_b = second
    if freq_a <= 0 or freq_b <= 0:
        raise ValueError("frequencies must be positive")
    return amp_a + amp_b


def beat_frequency(first, second):
    amp_a, freq_a = first
    amp_b, freq_b = second
    if amp_a < 0 or amp_b < 0:
        raise ValueError("amplitudes must be non-negative")
    return abs(freq_a - freq_b)


def validate_pair(pair):
    first, second = pair
    for signal in (first, second):
        if len(signal) != 2:
            raise ValueError("each signal needs an amplitude and a frequency")
    return tuple(first), tuple(second)


def mix(signals):
    mixed = []
    for pair in signals:
        first, second = validate_pair(pair)
        peak = combined_amplitude(first, second)
        beat = beat_frequency(first, second)
        mixed.append((peak, beat))
    return mixed


def describe(pair, result):
    first, second = pair
    peak, beat = result
    left = "{}@{}Hz".format(first[0], first[1])
    right = "{}@{}Hz".format(second[0], second[1])
    sources = "{} + {}".format(left, right)
    outcome = "peak {} beat {}Hz".format(peak, beat)
    return sources + " -> " + outcome


def report(signals):
    results = mix(signals)
    paired = zip(signals, results)
    lines = []
    for pair, result in paired:
        lines.append(describe(pair, result))
    return "\n".join(lines)


