def scale_box(box, factor):
    """Return a new box whose width and height are multiplied by factor."""
    width, height = box
    return (width * factor, height * factor)


def box_area(box):
    """Return the area of a (width, height) box."""
    width, height = box
    return width * height


def box_perimeter(box):
    """Return the perimeter of a (width, height) box."""
    width, height = box
    return 2 * (width + height)


def require_number(value, label):
    """Return value unchanged if it is an int or a float."""
    if type(value) not in (int, float):
        raise ValueError("{} must be a number".format(label))
    return value


def validate_entry(entry):
    """Check an entry and return it as a normalised (box, factor) pair."""
    if len(entry) != 2:
        raise ValueError("each entry must hold a box and a factor")
    raw_box, raw_factor = entry
    if len(raw_box) != 2:
        raise ValueError("each box must hold a width and a height")
    width = require_number(raw_box[0], "width")
    height = require_number(raw_box[1], "height")
    box = (width, height)
    factor = require_number(raw_factor, "factor")
    return (box, factor)


def resize(boxes):
    """Scale every box and report the resulting area and perimeter."""
    results = []
    for entry in boxes:
        box, factor = validate_entry(entry)
        scaled = scale_box(box, factor)
        area = box_area(scaled)
        perimeter = box_perimeter(scaled)
        results.append((area, perimeter))
    return results


def parse_number(text):
    """Convert text to an int when possible, otherwise to a float."""
    value = float(text.strip())
    if value.is_integer():
        return int(value)
    return value


def parse_spec(text):
    """Parse a 'WxH @ factor' specification into a (box, factor) entry."""
    dimensions, factor_text = text.split("@")
    width_text, height_text = dimensions.split("x")
    box = (parse_number(width_text), parse_number(height_text))
    return (box, parse_number(factor_text))


def format_report(entries, results):
    """Build human readable lines describing each resize operation."""
    lines = []
    for index, entry in enumerate(entries):
        box, factor = entry
        area, perimeter = results[index]
        lines.append(
            f"{box[0]}x{box[1]} scaled by {factor}"
            f" -> area {area}, perimeter {perimeter}"
        )
    return lines


def main():
    specs = [
        "2x3 @ 2",
        "1x1 @ 5",
        "4x2.5 @ 1",
        "10x6 @ 0.5",
    ]
    samples = [parse_spec(spec) for spec in specs]
    measurements = resize(samples)
    for line in format_report(samples, measurements):
        print(line)
    total_area = sum(item[0] for item in measurements)
    total_perimeter = sum(item[1] for item in measurements)
    print(f"totals: area {total_area}, perimeter {total_perimeter}")


if __name__ == "__main__":
    main()

