NUMERIC_TYPES = (int, float)


def margin(buy, sell):
    """Return the absolute profit margin obtained by buying at `buy` and selling at `sell`."""
    return sell - buy


def percentage_yield(buy, sell):
    """Return the profit margin expressed as a percentage of the buying price."""
    if buy == 0:
        raise ValueError("buying price must be non-zero to compute a percentage yield")
    return margin(buy, sell) / buy * 100.0


def validate_pair(pair):
    """Check a single market entry and return it as a (buy, sell) float tuple."""
    if len(pair) != 2:
        raise ValueError("each market entry needs exactly two rates, got %d" % len(pair))
    buy, sell = pair
    for rate in (buy, sell):
        if not isinstance(rate, NUMERIC_TYPES):
            raise TypeError("exchange rates must be numeric, got %r" % (rate,))
        if rate < 0:
            raise ValueError("exchange rates must not be negative, got %r" % (rate,))
    return float(buy), float(sell)


def trade(markets):
    """Evaluate every market pair and return a list of (margin, percentage yield) tuples."""
    results = []
    for pair in markets:
        buy, sell = validate_pair(pair)
        gain = margin(buy, sell)
        pct = percentage_yield(buy, sell)
        results.append((gain, pct))
    return results


def format_report(markets, results):
    """Build a human readable table of the evaluated opportunities."""
    header = "{:>10} {:>10} {:>10} {:>10}".format(
        "BUY",
        "SELL",
        "MARGIN",
        "YIELD %",
    )
    lines = [header, "-" * len(header)]
    for index, pair in enumerate(markets):
        buy, sell = validate_pair(pair)
        gain, pct = results[index]
        row = "{:>10.4f} {:>10.4f}".format(buy, sell)
