def lighter(first, second):
    """Return the lighter of two relative luminances."""
    return max(first, second)


def darker(first, second):
    """Return the darker of two relative luminances."""
    return min(first, second)


def contrast_ratio(light, dark):
    """Return the WCAG contrast ratio of a lighter and a darker luminance."""
    return (light + 0.05) / (dark + 0.05)


def validate_pair(pair):
    """Raise ValueError unless the pair holds two luminances inside [0, 1]."""
    if len(pair) != 2:
        raise ValueError("a comparison needs exactly 2 colors, got {}".format(len(pair)))
    for luminance in pair:
        if not 0.0 <= luminance <= 1.0:
            raise ValueError("luminance {} is outside [0, 1]".format(luminance))


def contrast(colors):
    """Return the contrast ratio of every pair, rounded to two decimals."""
    ratios = []
    for pair in colors:
        validate_pair(pair)
        first, second = pair
        light = lighter(first, second)
        dark = darker(first, second)
        ratio = contrast_ratio(light, dark)
        ratios.append(round(ratio, 2))
    return ratios


THRESHOLDS = [
    (7.0, "AAA"),
    (4.5, "AA"),
    (3.0, "AA large text"),
]


def grade(ratio):
    """Map a contrast ratio onto the WCAG conformance level it reaches."""
    for minimum, label in THRESHOLDS:
        if ratio >= minimum:
            return label
    return "fails"


def format_row(pair, ratio):
    """Render one comparison as an aligned report line."""
    first, second = pair
    numbers = "{:.2f} vs {:.2f} -> {:>5.2f}".format(first, second, ratio)
    return numbers + "  ({})".format(grade(ratio))


def report(colors):
    """Return a report line for each pair of colors."""
    ratios = contrast(colors)
    rows = []
    for pair, ratio in zip(colors, ratios):
        rows.append(format_row(pair, ratio))
    return rows


def main():
    samples = [
        (0.8, 0.2),
        (1.0, 0.0),
        (0.5, 0.5),
        (0.05, 0.45),
        (0.21, 0.02),
    ]
    print("ratios:", contrast(samples))
    for line in report(samples):
        print(line)


if __name__ == "__main__":
    main()

