import math

NUMBER_TYPES = (int,float)
ROW_FORMAT = "{0:>6} {1:>6} {2:>8} {3:>8}  {4}"


def left_multiplier(position):
    """Gain factor applied to the left channel for a pan position."""
    return math.sqrt(0.5 * (1.0 - position))


def right_multiplier(position):
    """Gain factor applied to the right channel for a pan position."""
    return math.sqrt(0.5 * (1.0 + position))


def apply_gain(volume,multiplier):
    """Scale a base volume by a channel multiplier."""
    return volume * multiplier


def validate_sound(volume,position):
    """Reject values the panning formulas cannot handle."""
    if not isinstance(volume,NUMBER_TYPES):
        raise TypeError("volume must be a number, got {0!r}".format(volume))
    if not isinstance(position,NUMBER_TYPES):
        raise TypeError("pan must be a number, got {0!r}".format(position))
    if volume < 0:
        raise ValueError("volume must not be negative: {0}".format(volume))
    if not -1.0 <= position <= 1.0:
        raise ValueError("pan must lie between -1 and 1: {0}".format(position))


def pan(sounds):
    """Return [(left, right)] volumes, rounded to two decimals, for each sound."""
    channels = []
    for volume,position in sounds:
        validate_sound(volume,position)
        left = apply_gain(volume,left_multiplier(position))
        right = apply_gain(volume,right_multiplier(position))
        channels.append((
            round(left,2),
            round(right,2),
        ))
    return channels


def describe_position(position):
    """Short human-readable label for a pan position."""
    if position <= -0.75:
        return "hard left"
    if position < -0.05:
        return "left of centre"
    if position <= 0.05:
        return "centre"
    if position < 0.75:
        return "right of centre"
    return "hard right"


def format_row(sound,channel):
    """Render one input sound beside its panned channel volumes."""
    volume,position = sound
    left,right = channel
    return ROW_FORMAT.format(
        volume,
        position,
        left,
        right,
        describe_position(position),
    )


def format_report(sounds,channels):
    """Build a table lining up each input with its panned output."""
    header = ROW_FORMAT.format(
        "vol",
        "pan",
        "left",
        "right",
        "image",
    )
    rows = [header,"-" * len(header)]
    for index,sound in enumerate(sounds):
        rows.append(format_row(sound,channels[index]))
    return "\n".join(rows)


