def split_name(name):
    """Split a full name into a (first, last) pair."""
    cleaned = " ".join(name.replace(",", " ").split())
    if not cleaned:
        raise ValueError("a profile entry must contain a first and last name")
    parts = cleaned.split(" ")
    if len(parts) != 2:
        raise ValueError("expected exactly two words, got: " + repr(cleaned))
    return parts[0], parts[1]


def upper_pair(first, last):
    """Return the pair with both components in upper case."""
    return first.upper(), last.upper()


def initial_pair(first, last):
    """Return the pair with the first name reduced to its initial."""
    return first[0].upper() + ".", last.capitalize()


def arrange(names):
    """Standardize profiles into uppercase and abbreviated string pairs."""
    arranged = []
    for name in names:
        first, last = split_name(name)
        arranged.append(upper_pair(first, last))
        arranged.append(initial_pair(first, last))
    return arranged


def format_pair(pair):
    """Render a single pair as 'First Last'."""
    return "{0} {1}".format(pair[0], pair[1])


def build_report(names):
    """Produce a report describing every arranged pair with its source."""
    lines = []
    for source in names:
        first, last = split_name(source)
        shouted = format_pair(upper_pair(first, last))
        shortened = format_pair(initial_pair(first, last))
        lines.append("uppercase: {0} -> {1}".format(source, shouted))
        lines.append("abbreviated: {0} -> {1}".format(source, shortened))
    return lines


def partition_valid(names):
    """Split raw entries into the usable ones and the rejected ones."""
    good = []
    bad = []
    for name in names:
        try:
            split_name(name)
        except ValueError as error:
            bad.append((name, str(error)))
        else:
            good.append(name)
    return good, bad


def main():
    raw = [
        "ada lovelace",
        "Grace Hopper",
        "alan  turing",
        "Katherine, Johnson",
        "Prince",
    ]
    usable, rejected = partition_valid(raw)
    for line in build_report(usable):
        print(line)
    for entry, reason in rejected:
        print("skipped {0!r}: {1}".format(entry, reason))
    print("pairs produced:", len(arrange(usable)))


if __name__ == "__main__":
    main()

