MIN_SPEED = 0.0
MAX_SPEED = 100.0
NUMBERS = (int, float)
HEADINGS = (
    "throttle",
    "steering",
    "left",
    "right",
)


def raw_speeds(throttle, steering):
    """Combine throttle and steering into unconstrained motor speeds."""
    left = throttle + steering
    right = throttle - steering
    return left, right


def clamp(speed):
    """Constrain a single motor speed to the inclusive range 0..100."""
    if speed < MIN_SPEED:
        return MIN_SPEED
    if speed > MAX_SPEED:
        return MAX_SPEED
    return speed


def clamp_pair(left, right):
    """Constrain both motor speeds to the inclusive range 0..100."""
    return clamp(left), clamp(right)


def check_number(value, label):
    """Return a flight input as a float, rejecting non-numeric values."""
    if type(value) not in NUMBERS:
        raise TypeError("{} is not numeric".format(label))
    return float(value)


def validate(commands):
    """Return the commands as a list of clean throttle/steering float pairs."""
    checked = []
    for index, command in enumerate(commands):
        if len(command) != 2:
            raise ValueError("command {} needs two values".format(index))
        throttle = check_number(command[0], "throttle of command {}".format(index))
        steering = check_number(command[1], "steering of command {}".format(index))
        checked.append((throttle, steering))
    return checked


def mix(commands):
    """Convert flight inputs into constrained left/right motor speed pairs."""
    speeds = []
    for command in validate(commands):
