TYPES = (list, tuple)
NUMBERS = (int, float)


def validate_prices(prices):
    if not isinstance(prices, TYPES):
        raise TypeError("prices must be given as a list or a tuple")
    for price in prices:
        if isinstance(price, bool):
            raise TypeError("booleans are not valid prices")
        if not isinstance(price, NUMBERS):
            raise TypeError("every price must be a real number, got %r" % (price,))
    return list(prices)


def update_low(price, current_low):
    if price < current_low:
        return price, True
    return current_low, False


def update_high(price, current_high):
    if price > current_high:
        return price, True
    return current_high, False


def track(prices):
    values = validate_prices(prices)
    if not values:
        return []
    low = high = values[0]
    bands = []
    for price in values:
        low_state = update_low(price, low)
        high_state = update_high(price, high)
        low = low_state[0]
        high = high_state[0]
        bands.append((low, high))
    return bands


def swing_flags(prices):
    values = validate_prices(prices)
    if not values:
        return []
    low = high = values[0]
    flags = []
    for price in values:
        low_state = update_low(price, low)
        high_state = update_high(price, high)
        low = low_state[0]
        high = high_state[0]
        flags.append((low_state[1], high_state[1]))
    return flags


def spread(band):
    return band[1] - band[0]


def format_row(step, price,
               band, flag):
    events = []
    if flag[0]:
        events.append("new low")
    if flag[1]:
        events.append("new high")
    label = ", ".join(events) or "steady"
    row = "{:>4}  {:>9.2f}  {:>9.2f}  {:>9.2f}  {:>9.2f}  {}"
    return row.format(step, price,
                      band[0], band[1],
                      spread(band), label)


def report(prices):
    bands = track(prices)
    flags = swing_flags(prices)
    head = "{:>4}  {:>9}  {:>9}  {:>9}  {:>9}  {}"
    lines = [head.format("step", "price",
                         "low", "high",
                         "spread", "events")]
    for step in range(len(bands)):
        lines.append(format_row(step + 1, prices[step],
                                bands[step], flags[step]))
    return lines


def main():
    feeds = {
        "AAPL": [189.4, 187.1,
                 190.6, 186.2,
                 191.8, 190.0],
        "MSFT": [401.0, 403.5,
                 399.2, 398.8,
                 404.1],
        "TSLA": [242.7, 250.3,
                 238.9, 231.4,
                 255.6, 249.9],
    }
    for symbol in sorted(feeds):
        prices = feeds[symbol]
        print("%s (%d ticks)" % (symbol, len(prices)))
        for line in report(prices):
            print("  " + line)
        final = track(prices)[-1]
        summary = "  window {:.2f} .. {:.2f} | volatility {:.2f}"
        print(summary.format(final[0], final[1],
                             spread(final)))
        print()


if __name__ == "__main__":
    main()

