DIE_FACES = range(1, 7)
ROLL_TYPES = (list, tuple)
DOUBLE_MULTIPLIER = 2


def validate_pair(pair):
    """Return the two dice of a roll pair, raising ValueError on bad input."""
    if not isinstance(pair, ROLL_TYPES):
        raise ValueError("each roll must be a list or tuple of dice: %r" % (pair,))
    if len(pair) != 2:
        raise ValueError("expected exactly 2 dice, got %d" % len(pair))
    first = pair[0]
    second = pair[1]
    for die in (first, second):
        if type(die) is not int:
            raise ValueError("die values must be integers: %r" % (die,))
        if die not in DIE_FACES:
            raise ValueError("die values must be within 1..6: %r" % (die,))
    return first, second


def analyze_dice(first, second):
    """Return the base sum of the two dice and whether they match as a pair."""
    return first + second, first == second


def evaluate_pair(total, matched):
    """Return the multiplied score and its classification."""
    if matched:
        return total * DOUBLE_MULTIPLIER, "double"
    return total, "normal"


def score(rolls):
    """Score every roll pair, returning (points, classification) tuples."""
    results = []
    for pair in rolls:
        first, second = validate_pair(pair)
        analysis = analyze_dice(first, second)
        results.append(evaluate_pair(*analysis))
    return results


def total_points(results):
    """Sum the points of all scored pairs."""
    return sum(points for points, _label in results)


def count_classifications(results):
    """Return how many pairs were doubles and how many were normal."""
    doubles = 0
    normals = 0
    for _points, label in results:
        if label == "double":
            doubles += 1
        else:
            normals += 1
    return doubles, normals


def format_report(rolls, results):
    """Build a human readable report of the scored game."""
    lines = ["    roll | points | kind"]
    rows = zip(rolls, results)
    for pair, outcome in rows:
        first, second = pair
        points, label = outcome
        roll_text = f"{first}+{second}"
        lines.append(f"{roll_text:>8} | {points:>6} | {label}")
    doubles, normals = count_classifications(results)
    lines.append(f"doubles: {doubles} | normals: {normals} | total: {total_points(results)}")
    return "\n".join(lines)


def main():
    rolls = [
        (3, 4),
        (5, 5),
        (1, 6),
        (2, 2),
        (6, 1),
        (4, 4),
    ]
    print(format_report(rolls, score(rolls)))


if __name__ == "__main__":
    main()

