import math

ALERT_LEVELS = [
    (6.0, "SEVERE"),
    (4.5, "HIGH"),
    (3.0, "MODERATE"),
    (1.5, "LOW"),
]

QUIET_ALERT = "QUIET"


def _check_amplitude(value, label):
    if not isinstance(value, (int, float)):
        raise TypeError("{} amplitude must be numeric, got {!r}".format(label, value))
    if value < 0:
        raise ValueError("{} amplitude must not be negative: {}".format(label, value))
    return float(value)


def measure_difference(primary, secondary):
    p = _check_amplitude(primary, "primary")
    s = _check_amplitude(secondary, "secondary")
    difference = p - s
    return difference, difference > 0


def rate_event(difference, positive):
    magnitude = round(math.log10(abs(difference) + 1.0) * 3.0, 2)
    if not positive:
        magnitude = round(magnitude * 0.5, 2)
    alert = QUIET_ALERT
    for floor, name in ALERT_LEVELS:
        if magnitude >= floor:
            alert = name
            break
    return magnitude, alert


def seismic(waves):
    results = []
    for pair in waves:
        primary, secondary = pair
        difference, positive = measure_difference(primary, secondary)
        results.append(rate_event(difference, positive))
    return results


def format_report(results):
    lines = ["{:>5}  {:>9}  {}".format("id", "magnitude", "alert")]
    for index, entry in enumerate(results, start=1):
        magnitude, alert = entry
        lines.append("{:>5}  {:>9.2f}  {}".format(index, magnitude, alert))
    return "\n".join(lines)


def summarize(results):
    counts = {}
    for _, alert in results:
        counts[alert] = counts.get(alert, 0) + 1
    ordered = [QUIET_ALERT] + [name for _, name in ALERT_LEVELS]
    parts = ["{}={}".format(name, counts[name]) for name in ordered if name in counts]
    return ", ".join(parts)


def main():
    readings = [
        (9.8, 1.2),
        (120.0, 15.5),
        (4.0, 4.0),
        (2.5, 7.5),
        (3000.0, 250.0),
    ]
    results = seismic(readings)
    print(format_report(results))
    print("station totals: {}".format(summarize(results)))


if __name__ == "__main__":
    main()

