"""Character frequency statistics for simple language models."""


def bump(counts, char):
    """Return the old count for *char* and the updated count as a pair."""
    old = counts.get(char, 0)
    new = old + 1
    counts[char] = new
    return old, new


def swap(char, count):
    """Return the pair (count, char) built from a character and its count."""
    return count, char


def count_characters(text):
    """Count every character of *text*, returning a dict of char -> count."""
    counts = {}
    for char in text:
        bump(counts, char)
    return counts


def ranked_pairs(counts):
    """Sort the (count, char) pairs from most to least frequent."""
    pairs = []
    for char, count in counts.items():
