    pairs.sort(key=lambda pair: (-pair[0], pair[1]))
    return pairs


def frequencies(text):
    """Return the highest character count and its character as a pair."""
    if not isinstance(text, str):
        raise TypeError("frequencies() expects a string, got %r" % type(text).__name__)
    if not text:
        return 0, ""
    return ranked_pairs(count_characters(text))[0]


def describe(char):
    """Give a printable name for a character, naming the invisible ones."""
    names = {
        " ": "space",
        "\t": "tab",
        "\n": "newline",
        "\r": "return",
    }
    return names.get(char, repr(char))


def report(text, top=3):
    """Format a short frequency report listing the *top* most common chars."""
    pairs = ranked_pairs(count_characters(text))
