"""Format integer cent amounts into dollar/cent string pairs."""

CENTS_PER_DOLLAR = 100


def split_amount(total, divisor):
    """Split a cent amount by the divisor, returning (dollars, remainder)."""
    sign = -1 if total < 0 else 1
    magnitude = abs(total)
    dollars = magnitude // divisor
    remainder = magnitude % divisor
    return sign * dollars, sign * remainder


def format_parts(dollars, remainder):
    """Turn a dollar count and a cent remainder into a pair of strings."""
    prefix = "-" if dollars < 0 or remainder < 0 else ""
    dollar_text = prefix + "{:,}".format(abs(dollars))
    cent_text = "{:02d}".format(abs(remainder))
    return dollar_text, cent_text


def validate(amounts):
    """Reject anything that is not a sequence of whole cent amounts."""
    scalar_types = (str, bytes)
    if isinstance(amounts, scalar_types):
        raise TypeError("amounts must be a list of integers")
    checked = []
    for index, amount in enumerate(amounts):
        if isinstance(amount, bool):
            raise TypeError("amount at position {} is a bool".format(index))
        if not isinstance(amount, int):
            raise TypeError("amount at position {} is not an integer".format(index))
        checked.append(amount)
    return checked


def coins(amounts):
    """Return a list of (dollar string, cent string) pairs for each amount."""
    results = []
    for amount in validate(amounts):
        parts = split_amount(amount, CENTS_PER_DOLLAR)
        results.append(format_parts(*parts))
    return results


def render(pair):
    """Render one formatted pair as a currency string."""
    dollar_text, cent_text = pair
    if dollar_text.startswith("-"):
        return "-${}.{}".format(dollar_text[1:], cent_text)
    return "${}.{}".format(dollar_text, cent_text)


def report(amounts):
    """Build a small ledger report: one rendered line per amount, plus a total."""
    pairs = coins(amounts)
    lines = []
    for index, amount in enumerate(amounts):
        rendered = render(pairs[index])
        lines.append("{:>12} cents -> {}".format(amount, rendered))
    total = sum(amounts)
    total_parts = split_amount(total, CENTS_PER_DOLLAR)
    total_text = render(format_parts(*total_parts))
    lines.append("{:>12} cents -> {}  (total)".format(total, total_text))
    return "\n".join(lines)


def main():
    ledger = [
        125, 9,
        100, 250000,
        -4575, 99,
    ]
    print(report(ledger))
    print()
    samples = [
        1, 10,
        1000, 123456,
    ]
    for pair in coins(samples):
        print("dollars={!r} cents={!r}".format(*pair))


if __name__ == "__main__":
    main()

