DISTANCE = 10.0
NUMBERS = (int, float)


def mechanical_advantage(effort, load):
    if effort == 0:
        raise ZeroDivisionError("effort force must be non-zero")
    return load / effort


def total_force(effort, load):
    return load + effort


def net_force_difference(effort, load):
    return abs(load - effort)


def total_work_proxy(effort, load):
    return total_force(effort, load) * DISTANCE


def _validate_pair(index, pair):
    try:
        effort, load = pair
    except (TypeError, ValueError):
        raise ValueError("measurement {} must be a pair of forces".format(index))
    for value in (effort, load):
        if type(value) not in NUMBERS:
            raise TypeError("measurement {} must hold numeric forces".format(index))
    return float(effort), float(load)


def normalise(forces):
    pairs = []
    for index, pair in enumerate(forces):
        pairs.append(_validate_pair(index, pair))
    return pairs


def leverage(forces):
    results = []
    for effort, load in normalise(forces):
        advantage = mechanical_advantage(effort, load)
        total = total_force(effort, load)
        results.append((advantage, total))
        difference = net_force_difference(effort, load)
        work = total_work_proxy(effort, load)
        results.append((difference, work))
    return results


def format_row(pair, rows):
    effort, load = pair
    advantage, total = rows[0]
    difference, work = rows[1]
    left = "{:>8.1f} {:>8.1f}".format(effort, load)
    middle = "{:>10.3f} {:>10.1f}".format(advantage, total)
    right = "{:>10.1f} {:>12.1f}".format(difference, work)
    return left + " " + middle + " " + right


def format_report(pairs, metrics):
    left = "{:>8} {:>8}".format("effort", "load")
    middle = "{:>10} {:>10}".format("advantage", "total")
    right = "{:>10} {:>12}".format("difference", "work")
    header = left + " " + middle + " " + right
    lines = [header]
    lines.append("-" * len(header))
    for index, pair in enumerate(pairs):
        rows = metrics[2 * index:2 * index + 2]
        lines.append(format_row(pair, rows))
    return "\n".join(lines)


def main():
    samples = [
        (50, 200),
        (25, 100),
        (120, 60),
        (10.5, 73.5),
    ]
    metrics = leverage(samples)
    print(format_report(samples, metrics))
    best = max(range(len(samples)), key=lambda i: metrics[2 * i][0])
    effort, load = samples[best]
    print("best advantage at effort {:.1f} N with load {:.1f} N".format(effort, load))


if __name__ == "__main__":
    main()

