import math
import numbers

HEADINGS = (
    "drop",
    "run",
    "distance",
    "gradient",
    "speed",
    "safety",
)
WIDTHS = (
    6,
    6,
    9,
    10,
    8,
    8,
)


def slope_distance(drop, run):
    exact = math.hypot(drop, run)
    return round(exact, 1)


def gradient_percent(drop, run):
    return round(drop / run * 100.0, 1)


def glide_speed(drop, run):
    return round(math.sqrt(19.6 * drop), 1)


def safety_rating(drop, run):
    return round(run ** 2 / drop, 1)


def validate(pair):
    if len(pair) != 2:
        raise ValueError("each slope needs a drop and a run: %r" % (pair,))
    named = zip(HEADINGS, pair)
    for name, value in named:
        if not isinstance(value, numbers.Real):
            raise TypeError("{} must be numeric but was {!r}".format(name, value))
        if value <= 0:
