PULSE_DURATION = 0.001
PAIR_TYPES = (tuple, list)
NUMERIC_TYPES = (int, float)
PRIMARY_LABELS = ("charge", "energy")
SECONDARY_LABELS = ("current", "force")


def stored_charge(capacitance, voltage):
    return capacitance * voltage


def stored_energy(capacitance, voltage):
    return 0.5 * capacitance * voltage ** 2


def displacement_current(capacitance, voltage):
    return stored_charge(capacitance, voltage) / PULSE_DURATION


def plate_force_proxy(capacitance, voltage):
    return capacitance ** 2 * voltage ** 2 / 2


def validate(component):
    if not isinstance(component, PAIR_TYPES):
        raise TypeError("each component must be a pair of numbers")
    if len(component) != 2:
        raise ValueError("each component needs a capacitance and a voltage")
    capacitance, voltage = component
    for value in (capacitance, voltage):
        if isinstance(value, bool):
            raise TypeError("capacitance and voltage must be numeric")
        if not isinstance(value, NUMERIC_TYPES):
            raise TypeError("capacitance and voltage must be numeric")
    if capacitance < 0:
        raise ValueError("capacitance cannot be negative")
    return float(capacitance), float(voltage)


def circuit(components):
    results = []
    for component in components:
        capacitance, voltage = validate(component)
        charge = stored_charge(capacitance, voltage)
        energy = stored_energy(capacitance, voltage)
        current = displacement_current(capacitance, voltage)
        force = plate_force_proxy(capacitance, voltage)
        results.append((charge, energy))
        results.append((current, force))
    return results


def format_pair(labels, values):
    return "{0}={1:.3g} {2}={3:.3g}".format(
        labels[0], values[0],
        labels[1], values[1],
    )


def report(components):
    metrics = circuit(components)
    lines = []
    for index, component in enumerate(components):
        lines.append("C={0}uF V={1}V".format(component[0], component[1]))
        lines.append("  " + format_pair(PRIMARY_LABELS, metrics[2 * index]))
        lines.append("  " + format_pair(SECONDARY_LABELS, metrics[2 * index + 1]))
    return "\n".join(lines)


def main():
    bank = [
        (10, 5),
        (4.7, 12),
        (100, 0.5),
        (0.22, 240),
    ]
    print(report(bank))
    metrics = circuit(bank)
    first_total = sum(pair[0] for pair in metrics)
    second_total = sum(pair[1] for pair in metrics)
    print("column sums: {0:.4g} {1:.4g}".format(first_total, second_total))


if __name__ == "__main__":
    main()

