import math


NUMERIC_TYPES = (int, float)
ROW_FORMAT = "{:8.1f} {:8.1f} {:10.3f} {:10.3f} {:10.3f} {:10.3f}"
HEADER = "{:>8} {:>8} {:>10} {:>10} {:>10} {:>10}".format(
    "k",
    "m",
    "omega^2",
    "period",
    "KE",
    "force",
)


def angular_frequency_squared(k, m):
    return k / m


def period_proxy(k, m):
    return 6.28 / math.sqrt(angular_frequency_squared(k, m))


def kinetic_energy(k, m):
    return 0.5 * k * 0.01


def peak_force(k, m):
    return k * 0.1 + m * 9.8


def validate_system(system):
    if len(system) != 2:
        raise ValueError("each spring system needs exactly two values")
    k, m = system
    labelled = [
        ("spring constant", k),
        ("mass", m),
    ]
    for name, value in labelled:
        if not isinstance(value, NUMERIC_TYPES):
            raise TypeError("{} must be numeric: {!r}".format(name, value))
        if value <= 0:
            raise ValueError("{} must be positive: {}".format(name, value))
    return float(k), float(m)


def oscillation(springs):
    results = []
    for system in springs:
        k, m = validate_system(system)
        results.append([
            angular_frequency_squared(k, m),
            period_proxy(k, m),
        ])
        results.append([
            kinetic_energy(k, m),
            peak_force(k, m),
        ])
    return results


def format_report(springs, metrics):
    lines = [HEADER]
    for index, system in enumerate(springs):
        k, m = validate_system(system)
        omega2, period = metrics[2 * index]
        energy, force = metrics[2 * index + 1]
        lines.append(ROW_FORMAT.format(
            k,
            m,
            omega2,
            period,
            energy,
            force,
        ))
    return "\n".join(lines)


def stiffest_system(springs):
    return max(springs, key=lambda system: validate_system(system)[0])


def main():
    springs = [
        [400, 4],
        [250, 2.5],
        [1200, 15],
        [80, 0.5],
    ]
    print(format_report(springs, oscillation(springs)))
    k, m = stiffest_system(springs)
    force = peak_force(k, m)
    print("stiffest spring has k={} N/m".format(k))
    print("its mass of {} kg gives a peak force of {:.2f} N".format(m, force))


if __name__ == "__main__":
    main()

