COEFFICIENT = 0.0001
ELASTIC_MODULUS = 200000
NUMERIC_TYPES = (int, float)


def expansion(length, delta_t):
    return length * delta_t * COEFFICIENT


def final_length(length, delta_t):
    return length + expansion(length, delta_t)


def strain_percent(length, delta_t):
    return expansion(length, delta_t) / length * 100


def confined_stress(length, delta_t):
    return expansion(length, delta_t) / length * ELASTIC_MODULUS


def validate(scenario):
    length, delta_t = scenario
    if not isinstance(length, NUMERIC_TYPES):
        raise TypeError("length must be numeric, got %r" % (length,))
    if not isinstance(delta_t, NUMERIC_TYPES):
        raise TypeError("temperature change must be numeric, got %r" % (delta_t,))
    if length <= 0:
        raise ValueError("length must be positive, got %r" % (length,))
    return float(length), float(delta_t)


def thermal(materials):
    results = []
    for scenario in materials:
        length, delta_t = validate(scenario)
        results.append((
            expansion(length, delta_t),
            final_length(length, delta_t),
        ))
        results.append((
            strain_percent(length, delta_t),
            confined_stress(length, delta_t),
        ))
    return results


def format_row(scenario, pairs):
    length, delta_t = scenario
    growth_pair, load_pair = pairs
    grown, ending = growth_pair
    strain, stress = load_pair
    fields = [
        "L0=%.3f m" % length,
        "dT=%+.1f C" % delta_t,
        "dL=%.5f m" % grown,
        "L1=%.5f m" % ending,
        "strain=%.4f %%" % strain,
        "stress=%.1f MPa" % stress,
    ]
    return " | ".join(fields)


def report(materials):
    metrics = thermal(materials)
    lines = []
    for index, scenario in enumerate(materials):
