STROKE_WORK_FACTOR = 1.2
STAGES = (
    ("hypertensive crisis", 180, 120),
    ("stage 2 hypertension", 140, 90),
    ("stage 1 hypertension", 130, 80),
    ("elevated", 120, 0),
)


def pulse_pressure(systolic, diastolic):
    return round(systolic - diastolic, 1)


def mean_arterial_pressure(systolic, diastolic):
    return round(diastolic + (systolic - diastolic) / 3.0, 1)


def stroke_work_index(systolic, diastolic):
    return round((systolic - diastolic) * STROKE_WORK_FACTOR, 1)


def wall_stress_proxy(systolic, diastolic):
    return round(systolic * diastolic / 100.0, 1)


def _validated(reading):
    if len(reading) != 2:
        raise ValueError("each reading needs a systolic and a diastolic value")
    systolic, diastolic = reading
    if systolic <= diastolic:
        raise ValueError("systolic pressure must exceed diastolic pressure")
    return float(systolic), float(diastolic)


def pressure(patients):
    results = []
    for reading in patients:
        systolic, diastolic = _validated(reading)
        pulse = pulse_pressure(systolic, diastolic)
        arterial = mean_arterial_pressure(systolic, diastolic)
        results.append((pulse, arterial))
        work = stroke_work_index(systolic, diastolic)
        stress = wall_stress_proxy(systolic, diastolic)
        results.append((work, stress))
    return results


def classify(systolic, diastolic):
    for label, systolic_limit, diastolic_limit in STAGES:
        if systolic >= systolic_limit or diastolic >= diastolic_limit:
            return label
    return "normal"


def format_row(systolic, diastolic, metrics):
    first, second = metrics
    pulse, arterial = first
    work, stress = second
    stage = classify(systolic, diastolic)
    template = "{:.0f}/{:.0f} -> PP={}, MAP={}, SWI={}, WSP={} ({})"
    return template.format(systolic, diastolic, pulse, arterial, work, stress, stage)


def main():
    readings = [
        (120, 80),
        (140, 90),
        (100, 60),
        (185, 125),
    ]
    metrics = pressure(readings)
    for index, reading in enumerate(readings):
        systolic, diastolic = reading
        pair = metrics[2 * index:2 * index + 2]
        print(format_row(systolic, diastolic, pair))


if __name__ == "__main__":
    main()

