NUMBER_TYPES = (int, float)

METRIC_LABELS = (
    "total area",
    "singles area",
    "service box",
    "boundary tape",
)


def total_area(length, width):
    return length * width


def singles_area(length, width):
    return length * (width - 9)


def service_box_area(length, width):
    return (length / 2) * ((width - 9) / 2)


def boundary_tape(length, width):
    return 2 * length + 2 * width


def validate_court(court):
    if len(court) != 2:
        raise ValueError("each court needs a length and a width")
    length, width = court
    fields = (
        ("length", length),
        ("width", width),
    )
    for name, value in fields:
        if not isinstance(value, NUMBER_TYPES):
            raise TypeError("court {} must be numeric".format(name))
        if value <= 0:
            raise ValueError("court {} must be positive".format(name))
    if width <= 9:
        raise ValueError("width {} leaves no singles court".format(width))
    return float(length), float(width)


def tennis(courts):
    results = []
    for court in courts:
        length, width = validate_court(court)
        results.append((
            total_area(length, width),
            singles_area(length, width),
        ))
        results.append((
            service_box_area(length, width),
            boundary_tape(length, width),
        ))
    return results


def trim(value):
    if float(value).is_integer():
        return str(int(value))
    return "{:.2f}".format(value).rstrip("0").rstrip(".")


def report(courts):
    metrics = tennis(courts)
    lines = []
    for index, court in enumerate(courts):
        values = metrics[2 * index] + metrics[2 * index + 1]
        lines.append("Court {} ({} x {} ft)".format(
            index + 1,
            trim(court[0]),
            trim(court[1]),
        ))
        for label, value in zip(METRIC_LABELS, values):
            lines.append("  {:<13} {}".format(label + ":", trim(value)))
    return "\n".join(lines)


def main():
    courts = [
        (78, 36),
        (78, 27),
        (60, 27),
        (36, 18),
    ]
    print(report(courts))


if __name__ == "__main__":
    main()

