import numbers

GRAVITY = 9.8
PULLEY_RADIUS = 1
MAX_MOTOR_FORCE = 5000


def unbalanced_mass(cabin_mass, counterweight_mass):
    return abs(cabin_mass - counterweight_mass)


def required_torque(cabin_mass, counterweight_mass):
    imbalance = unbalanced_mass(cabin_mass, counterweight_mass)
    return round(imbalance * GRAVITY * PULLEY_RADIUS, 2)


def system_inertia(cabin_mass, counterweight_mass):
    return cabin_mass + counterweight_mass


def max_acceleration(cabin_mass, counterweight_mass):
    inertia = system_inertia(cabin_mass, counterweight_mass)
    if inertia == 0:
        raise ValueError("system inertia proxy must be greater than zero")
    return round(MAX_MOTOR_FORCE / inertia, 2)


def validate_mass(label, mass):
    if not isinstance(mass, numbers.Real):
        raise TypeError("{} mass must be numeric".format(label))
    if mass < 0:
        raise ValueError("{} mass must not be negative".format(label))
    return mass


def validate_system(config):
    if len(config) != 2:
        raise ValueError("each configuration needs exactly two masses")
    cabin_mass, counterweight_mass = config
    validate_mass("cabin", cabin_mass)
    validate_mass("counterweight", counterweight_mass)
    return cabin_mass, counterweight_mass


def elevator(systems):
    results = []
    for config in systems:
        cabin_mass, counterweight_mass = validate_system(config)
        imbalance = unbalanced_mass(cabin_mass, counterweight_mass)
        torque = required_torque(cabin_mass, counterweight_mass)
        inertia = system_inertia(cabin_mass, counterweight_mass)
        acceleration = max_acceleration(cabin_mass, counterweight_mass)
        results.append((imbalance, torque))
        results.append((inertia, acceleration))
    return results


def format_report(systems, metrics):
    lines = []
    for index, config in enumerate(systems):
        imbalance, torque = metrics[2 * index]
        inertia, acceleration = metrics[2 * index + 1]
        lines.append("Elevator {}".format(index + 1))
        lines.append("  cabin {} kg | counterweight {} kg".format(*config))
        lines.append("  imbalance {} kg | torque {} Nm".format(imbalance, torque))
        lines.append("  inertia {} kg | max acceleration {}".format(inertia, acceleration))
    return "\n".join(lines)


def main():
    systems = [
        (1000, 1200),
        (1500, 1500),
        (800, 650),
        (2000, 1750),
    ]
    metrics = elevator(systems)
    print(format_report(systems, metrics))


if __name__ == "__main__":
    main()

