FRICTION_FACTOR = 1.02
HEAT_FACTOR = 1.05
RUSH_SPEED_BOOST = 1.2
SPEED_LIMITS = (5.0, 8.0)
TEMPERATURE_LIMITS = (90.0, 120.0)
NIGHT_LOG_LINES = [
    "4.0 80.0",
    "7.9 91.0",
    "9.5 130.0",
]
NIGHT_LOG = "\n".join(NIGHT_LOG_LINES)


def exceeds_warning(value, warning_limit):
    return value * FRICTION_FACTOR > warning_limit


def exceeds_shutdown(value, shutdown_limit):
    return value * HEAT_FACTOR > shutdown_limit


def parse_record(line):
    fields = line.split()
    if len(fields) != 2:
        raise ValueError("a log line needs a speed and a temperature: {!r}".format(line))
    return float(fields[0]), float(fields[1])


def limits_for_run(rush):
    speed_warning, speed_shutdown = SPEED_LIMITS
    if rush:
        speed_shutdown *= RUSH_SPEED_BOOST
    speed_limits = (speed_warning, speed_shutdown)
    return speed_limits, TEMPERATURE_LIMITS


def count_breaches(value, limits):
    warning_limit, shutdown_limit = limits
    breaches = [0, 0]
    if exceeds_warning(value, warning_limit):
        breaches[0] += 1
    if exceeds_shutdown(value, shutdown_limit):
        breaches[1] += 1
    return breaches


def assembly(records, rush):
    counts = [0, 0]
    speed_limits, temperature_limits = limits_for_run(rush)
    for line in records.splitlines():
        if not line.strip():
            continue
        speed, temperature = parse_record(line)
        speed_breaches = count_breaches(speed, speed_limits)
        heat_breaches = count_breaches(temperature, temperature_limits)
        counts[0] += speed_breaches[0] + heat_breaches[0]
        counts[1] += speed_breaches[1] + heat_breaches[1]
    return counts


def format_report(label, counts):
    warnings, shutdowns = counts
    parts = [
        "{} warning(s)".format(warnings),
        "{} shutdown(s)".format(shutdowns),
    ]
    joined = ", ".join(parts)
    return "{}: {}".format(label, joined)


def main():
    shifts = [
        ("single reading", "6.0 95.0"),
        ("night shift", NIGHT_LOG),
    ]
    for label, records in shifts:
        counts = assembly(records, False)
        print(format_report(label, counts))
    rush_counts = assembly(NIGHT_LOG, True)
    print(format_report("night shift under rush", rush_counts))


if __name__ == "__main__":
    main()

