WIND_OFFSET = 1.5
DRAG_OFFSET = 3.0
WIND_LIMITS = (15.0, 25.0)
DRAIN_LIMITS = (10.0, 18.0)
PAYLOAD_DERATE = 0.9


def exceeds_caution(value, caution_limit):
    return value + WIND_OFFSET > caution_limit


def exceeds_return(value, return_limit):
    return value + DRAG_OFFSET > return_limit


def parse_line(line):
    fields = line.split()
    if len(fields) != 2:
        raise ValueError("expected two fields in {!r}".format(line))
    return float(fields[0]), float(fields[1])


def drone(stream, payload):
    counts = [0, 0]
    wind_caution, wind_return = WIND_LIMITS
    drain_caution, drain_return = DRAIN_LIMITS
    if payload:
        drain_return *= PAYLOAD_DERATE
    for line in stream.splitlines():
        stripped = line.strip()
        if not stripped:
            continue
        wind, drain = parse_line(stripped)
        if exceeds_caution(wind, wind_caution):
            counts[0] += 1
        if exceeds_return(wind, wind_return):
            counts[1] += 1
        if exceeds_caution(drain, drain_caution):
            counts[0] += 1
        if exceeds_return(drain, drain_return):
            counts[1] += 1
    return counts


def format_report(label, counts):
    pieces = [
        "flight {}".format(label),
        "cautions {}".format(counts[0]),
        "returns {}".format(counts[1]),
    ]
    return " | ".join(pieces)


def summarize(flights, payload):
    lines = []
    for label, stream in flights:
        counts = drone(stream, payload)
        lines.append(format_report(label, counts))
    return lines


def main():
    calm = "\n".join(["4.0 3.0", "8.5 6.0"])
    gusty = "\n".join(["16.0 12.0", "23.5 15.5"])
    storm = "\n".join(["28.0 20.0", "14.0 17.0"])
    flights = [
        ("calm", calm),
        ("gusty", gusty),
        ("storm", storm),
    ]
    print("unloaded:")
    for report in summarize(flights, False):
        print(report)
    print("loaded:")
    for report in summarize(flights, True):
        print(report)


if __name__ == "__main__":
    main()

