WEAR_FACTOR = 1.1
STRESS_FACTOR = 1.2

VIBRATION_WARNING_LIMIT = 4.0
VIBRATION_EMERGENCY_LIMIT = 7.5
TORQUE_WARNING_LIMIT = 500.0
TORQUE_EMERGENCY_LIMIT = 800.0
STORM_DERATING = 0.85


def exceeds_warning(value, warning_limit):
    """True when the worn value strictly exceeds the given warning limit."""
    return value * WEAR_FACTOR > warning_limit


def exceeds_emergency(value, emergency_limit):
    """True when the stressed value strictly exceeds the given emergency limit."""
    return value * STRESS_FACTOR > emergency_limit


def parse_line(line):
    """Split one sensor line into a (vibration, torque) pair of floats."""
    parts = line.split()
    if len(parts) != 2:
        raise ValueError("a sensor line needs a vibration and a torque: " + line)
    return float(parts[0]), float(parts[1])


def torque_emergency_limit(storm):
    """Storm conditions lower the torque emergency limit by fifteen percent."""
    if storm:
        return TORQUE_EMERGENCY_LIMIT * STORM_DERATING
    return TORQUE_EMERGENCY_LIMIT


def turbine(sensors, storm):
    """Count warning and emergency events across all sensor lines."""
    counts = [0, 0]
    torque_emergency = torque_emergency_limit(storm)
    for line in sensors.splitlines():
        if not line.strip():
            continue
        vibration, torque = parse_line(line)
        if exceeds_warning(vibration, VIBRATION_WARNING_LIMIT):
            counts[0] += 1
        if exceeds_warning(torque, TORQUE_WARNING_LIMIT):
            counts[0] += 1
        if exceeds_emergency(vibration, VIBRATION_EMERGENCY_LIMIT):
            counts[1] += 1
        if exceeds_emergency(torque, torque_emergency):
            counts[1] += 1
    return counts


def format_report(storm, counts):
    """Render one turbine result as a single readable line."""
    weather = "storm" if storm else "calm"
    warnings = "{} warning(s)".format(counts[0])
    emergencies = "{} emergency(ies)".format(counts[1])
    events = [warnings, emergencies]
    return "[" + weather + "] " + " and ".join(events)


SAMPLES = [
    ("3.8 550.0", False),
    ("2.0 300.0\n1.5 410.0", False),
    ("3.8 550.0\n7.0 690.0", True),
    ("8.2 820.0\n6.9 700.0", False),
]


def main():
    for readings, storm in SAMPLES:
        counts = turbine(readings, storm)
        print(format_report(storm, counts))


if __name__ == "__main__":
    main()

