PRE_AMP_GAIN = 0.05
MASTERING_GAIN = 0.1


def exceeds_peak(value, peak_limit):
    return value + PRE_AMP_GAIN > peak_limit


def exceeds_clip(value, clip_limit):
    return value + MASTERING_GAIN > clip_limit


def parse_line(line):
    parts = line.split()
    if len(parts) != 2:
        raise ValueError("expected two readings, got: " + line)
    left, right = float(parts[0]), float(parts[1])
    return left, right


def channel_limits(boost):
    left = {"peak": 0.8, "clip": 0.95}
    right = {"peak": 0.8, "clip": 0.95}
    if boost:
        right["clip"] = right["clip"] * 0.95
    return left, right


def audio(samples, boost):
    counts = [0, 0]
    left_limits, right_limits = channel_limits(boost)
    for line in samples.splitlines():
        if not line.strip():
            continue
        left, right = parse_line(line)
        if exceeds_peak(left, left_limits["peak"]):
            counts[0] += 1
        if exceeds_clip(left, left_limits["clip"]):
            counts[1] += 1
        if exceeds_peak(right, right_limits["peak"]):
            counts[0] += 1
        if exceeds_clip(right, right_limits["clip"]):
            counts[1] += 1
    return counts


def format_report(label, counts):
    return "{0}: peaks={1}, clips={2}".format(label, counts[0], counts[1])


def main():
    recordings = [
        ("take-1", "0.78 0.78", False),
        ("take-2", "0.90 0.91\n0.40 0.55\n0.86 0.88", False),
        ("take-3", "0.90 0.91\n0.40 0.55\n0.86 0.88", True),
    ]
    lines = []
    for label, samples, boost in recordings:
        counts = audio(samples, boost)
        lines.append(format_report(label, counts))
    print("\n".join(lines))


if __name__ == "__main__":
    main()

