text_nat:
CPU_LIMITS = (70.0, 90.0)
MEMORY_LIMITS = (80.0, 95.0)
BACKGROUND_TASK_OVERHEAD = 5.0
SYSTEM_OVERHEAD = 10.0
PREMIUM_CPU_BONUS = 1.05


def exceeds_throttle_limit(value, throttle_limit):
    """True when the value plus background task overhead passes the throttle limit."""
    return value + BACKGROUND_TASK_OVERHEAD > throttle_limit


def exceeds_overload_limit(value, overload_limit):
    """True when the value plus system overhead passes the overload limit."""
    return value + SYSTEM_OVERHEAD > overload_limit


def parse_sample(line):
    """Split a single metrics line into a (cpu, memory) pair of floats."""
    fields = line.split()
    if len(fields) != 2:
        raise ValueError("expected 'cpu memory', got: " + line)
    cpu, memory = fields
    return float(cpu), float(memory)


def parse_metrics(metrics):
    samples = []
    for line in metrics.splitlines():
        stripped = line.strip()
        if stripped:
            samples.append(parse_sample(stripped))
    return samples


def effective_limits(premium):
    """Return cpu throttle, cpu overload, memory throttle and memory overload limits."""
    cpu_throttle, cpu_overload = CPU_LIMITS
    memory_throttle, memory_overload = MEMORY_LIMITS
    if premium:
        cpu_overload *= PREMIUM_CPU_BONUS
    return cpu_throttle, cpu_overload, memory_throttle, memory_overload


def server(metrics, premium):
    events = [0, 0]
    cpu_throttle, cpu_overload, memory_throttle, memory_overload = effective_limits(premium)
    for cpu, memory in parse_metrics(metrics):
        if exceeds_throttle_limit(cpu, cpu_throttle):
            events[0] += 1
        if exceeds_throttle_limit(memory, memory_throttle):
            events[0] += 1
        if exceeds_overload_limit(cpu, cpu_overload):
            events[1] += 1
        if exceeds_overload_limit(memory, memory_overload):
            events[1] += 1
    return events


def format_report(events, premium):
    throttles, overloads = events
    plan = "premium" if premium else "standard"
    parts = ["plan=" + plan, "throttles={}".format(throttles), "overloads={}".format(overloads)]
