text_nat:
SHOE_WEIGHT_PENALTY = 0.5
FATIGUE_PENALTY = 1.5
SPEED_LIMITS = (6.0, 10.0)
RESERVE_LIMITS = (50.0, 80.0)
INCLINE_FACTOR = 0.9


def exceeds_aerobic_limit(value, aerobic_limit):
    return value + SHOE_WEIGHT_PENALTY > aerobic_limit


def exceeds_anaerobic_limit(value, anaerobic_limit):
    return value + FATIGUE_PENALTY > anaerobic_limit


def classify(value, limits):
    aerobic_limit, anaerobic_limit = limits
    if exceeds_anaerobic_limit(value, anaerobic_limit):
        return "anaerobic"
    if exceeds_aerobic_limit(value, aerobic_limit):
        return "threshold"
    return "aerobic"


def parse_line(line):
    fields = line.split()
    if len(fields) != 2:
        raise ValueError("expected a speed and a heart reserve in: " + line)
    return float(fields[0]), float(fields[1])


def parse_sessions(sessions):
    return [parse_line(line) for line in sessions.splitlines() if line.strip()]


def speed_limits(incline):
    aerobic_limit, anaerobic_limit = SPEED_LIMITS
    if incline:
        return aerobic_limit, anaerobic_limit * INCLINE_FACTOR
    return aerobic_limit, anaerobic_limit


def treadmill(sessions, incline):
    counts = [0, 0]
    limits = speed_limits(incline)
    for speed, reserve in parse_sessions(sessions):
        speed_zone = classify(speed, limits)
        reserve_zone = classify(reserve, RESERVE_LIMITS)
        for zone in [speed_zone, reserve_zone]:
            if zone == "anaerobic":
                counts[1] += 1
            else:
                counts[0] += 1
    return counts


def format_report(sessions, incline):
    limits = speed_limits(incline)
    lines = []
    for speed, reserve in parse_sessions(sessions):
        speed_zone = classify(speed, limits)
        reserve_zone = classify(reserve, RESERVE_LIMITS)
        row = "{:>5.1f} mph -> {}".format(speed, speed_zone)
        row += "   {:>6.1f}% -> {}".format(reserve, reserve_zone)
        lines.append(row)
    counts = treadmill(sessions, incline)
    lines.append("aerobic={} anaerobic={}".format(counts[0], counts[1]))
    return "\n".join(lines)


def main():
    log = "5.8 49.5\n7.2 62.0\n9.4 83.5"
    for incline in [False, True]:
        print("incline = {}".format(incline))
        print(format_report(log, incline))
    print(treadmill("5.8 49.5", False))


if __name__ == "__main__":
    main()

