TEMPERATURE_LIMITS = (500.0, 800.0)
VIBRATION_LIMITS = (50.0, 90.0)
ORBIT_DANGER_FACTOR = 1.1


def exceeds_warning(value, warning_limit):
    return value + SOLAR_RADIATION > warning_limit


def exceeds_danger(value, danger_limit):
    return value + ENGINE_EXHAUST > danger_limit


def parse_line(line):
    fields = line.split()
