        raise ValueError("expected 2 fields, got {} in {!r}".format(len(fields), line))
    temperature = float(fields[0])
    vibration = float(fields[1])
    return [temperature, vibration]


def temperature_limits(orbit):
    warning_limit, danger_limit = TEMPERATURE_LIMITS
    if orbit:
        danger_limit *= ORBIT_DANGER_FACTOR
    return [warning_limit, danger_limit]


def rocket(stream, orbit):
    counts = [0, 0]
    temp_warning, temp_danger = temperature_limits(orbit)
    vib_warning, vib_danger = VIBRATION_LIMITS
    for line in stream.splitlines():
        line = line.strip()
        if not line:
            continue
        temperature, vibration = parse_line(line)
        if exceeds_warning(temperature, temp_warning):
            counts[0] += 1
        if exceeds_warning(vibration, vib_warning):
            counts[0] += 1
        if exceeds_danger(temperature, temp_danger):
            counts[1] += 1
        if exceeds_danger(vibration, vib_danger):
            counts[1] += 1
    return counts


def format_report(counts, orbit):
    mode = "high orbit" if orbit else "low orbit"
    warnings, dangers = counts
    return f"{mode}: {warnings} warning(s), {dangers} danger(s)"


def main():
