text_nat:
"""Analysis of electric vehicle charge logs (cell voltage and casing temperature)."""

AGE_RESISTANCE = 0.1
SHORT_CIRCUIT_RISK = 0.3
VOLTAGE_WEAR_LIMIT = 4.2
VOLTAGE_RUNAWAY_LIMIT = 4.5
TEMPERATURE_WEAR_LIMIT = 40.0
TEMPERATURE_RUNAWAY_LIMIT = 60.0
FAST_CHARGE_DERATING = 0.95


def wear_breach(value, limit):
    """True when the value, grown by the age resistance, strictly exceeds the wear limit."""
    return value * (1.0 + AGE_RESISTANCE) > limit


def runaway_breach(value, limit):
    """True when the value, plus the short circuit risk, strictly exceeds the runaway limit."""
    return value + SHORT_CIRCUIT_RISK > limit


def parse_line(line):
    fields = line.split()
    if len(fields) != 2:
        raise ValueError("expected a voltage and a temperature: " + repr(line))
    return float(fields[0]), float(fields[1])


def parse_logs(logs):
    readings = []
    for line in logs.splitlines():
        if line.strip():
            readings.append(parse_line(line))
    return readings


def battery(logs, fast):
    counts = [0, 0]
    temperature_runaway_limit = TEMPERATURE_RUNAWAY_LIMIT
    if fast:
        temperature_runaway_limit *= FAST_CHARGE_DERATING
    for voltage, temperature in parse_logs(logs):
        if wear_breach(voltage, VOLTAGE_WEAR_LIMIT):
            counts[0] += 1
        if wear_breach(temperature, TEMPERATURE_WEAR_LIMIT):
            counts[0] += 1
        if runaway_breach(voltage, VOLTAGE_RUNAWAY_LIMIT):
            counts[1] += 1
        if runaway_breach(temperature, temperature_runaway_limit):
            counts[1] += 1
    return counts


def peaks(readings):
    voltages = [voltage for voltage, _ in readings]
    temperatures = [temperature for _, temperature in readings]
    return max(voltages), max(temperatures)


def format_report(label, counts):
    breaches = "wear {} / runaway {}".format(counts[0], counts[1])
    return "{:>8} charge -> {}".format(label, breaches)


def main():
    lines = [
        "4.15 39.9",
        "4.55 41.0",
        "3.90 62.5",
        "4.21 57.4",
    ]
    logs = "\n".join(lines)
    readings = parse_logs(logs)
    peak_voltage, peak_temperature = peaks(readings)
