def exceeds_warning(value, warning_limit):
    return value * RUST_FACTOR > warning_limit


def exceeds_danger(value, danger_limit):
    return value * STAGNATION_FACTOR > danger_limit


def parse_line(line):
    parts = line.split()
    if len(parts) != 2:
        raise ValueError("expected two values per line: " + line)
    return float(parts[0]), float(parts[1])


def limits_for(flood):
    chlorine = (3.0, 5.0)
    turbidity_warning = 10.0
    turbidity_danger = 25.0
    if flood:
        turbidity_danger *= 0.9
    turbidity = (turbidity_warning, turbidity_danger)
    return chlorine, turbidity


def water(samples, flood):
    counts = [0, 0]
    chlorine_limits, turbidity_limits = limits_for(flood)
