        chlorine, turbidity = parse_line(stripped)
        if exceeds_warning(chlorine, chlorine_warning):
            counts[0] += 1
        if exceeds_warning(turbidity, turbidity_warning):
            counts[0] += 1
        if exceeds_danger(chlorine, chlorine_danger):
            counts[1] += 1
        if exceeds_danger(turbidity, turbidity_danger):
            counts[1] += 1
    return counts


