MINUTE_LIMITS = (30.0, 90.0)
PRO_DISCOUNT = 0.10


def meets_goal(value, goal_limit):
    return value + WARM_UP_BONUS > goal_limit


def meets_exceptional(value, exceptional_limit):
    return value + COOL_DOWN_BONUS > exceptional_limit


def parse_session(line):
    parts = line.split()
    if len(parts) != 2:
        raise ValueError("expected 'calories minutes', got: %r" % line)
