BLOCKED_VENT_FACTOR = 15.0
TEMPERATURE_LIMITS = (70.0, 90.0)
FAN_LIMITS = (2000.0, 3000.0)
STEREO_OVERHEAT_SCALE = 0.9


def exceeds_warm_limit(value, warm_limit):
    return value + DUST_INSULATION_FACTOR > warm_limit


def exceeds_overheat_limit(value, overheat_limit):
    return value + BLOCKED_VENT_FACTOR > overheat_limit


def parse_line(line):
    fields = line.split()
    if len(fields) != 2:
        raise ValueError("each frame needs two fields: temperature, fan speed")
    temperature, fan_speed = fields
    return float(temperature), float(fan_speed)


def parse_frames(frames):
    readings = []
    for line in frames.splitlines():
        stripped = line.strip()
        if stripped:
            readings.append(parse_line(stripped))
    return readings


def cinema(frames, stereo):
    counts = [0, 0]
    temperature_warm, temperature_overheat = TEMPERATURE_LIMITS
    fan_warm, fan_overheat = FAN_LIMITS
    if stereo:
        temperature_overheat *= STEREO_OVERHEAT_SCALE
    for temperature, fan_speed in parse_frames(frames):
        if exceeds_warm_limit(temperature, temperature_warm):
            counts[0] += 1
        if exceeds_warm_limit(fan_speed, fan_warm):
