NUMBER_TYPES = (int, float)


def _validate(base, tint):
    if not isinstance(base, NUMBER_TYPES):
        raise TypeError("base volume must be a number, got %r" % (base,))
    if not isinstance(tint, NUMBER_TYPES):
        raise TypeError("tint volume must be a number, got %r" % (tint,))
    if base <= 0:
        raise ValueError("base volume must be positive, got %r" % (base,))
    if tint < 0:
        raise ValueError("tint volume must not be negative, got %r" % (tint,))


def total_volume(base, tint):
    return base + tint


def excess_tint(base, tint):
    return abs(tint - base / 2.0)


def coverage_area(base, tint):
    total = total_volume(base, tint)
    return total * base


def vibrancy_index(base, tint):
    excess = excess_tint(base, tint)
    total = total_volume(base, tint)
    return excess * excess / total


def proportion(base, tint):
    _validate(base, tint)
    area = coverage_area(base, tint)
    vibrancy = vibrancy_index(base, tint)
    return area + vibrancy


METRICS = (
    ("total volume", total_volume),
    ("excess tint", excess_tint),
    ("coverage area", coverage_area),
    ("vibrancy index", vibrancy_index),
    ("proportion", proportion),
)


def mix_table(base, tint):
    _validate(base, tint)
    rows = []
    for label, metric in METRICS:
        value = metric(base, tint)
        rows.append((label, value))
    return rows


def describe_mix(base, tint):
    rows = mix_table(base, tint)
    width = max(len(row[0]) for row in rows)
    lines = ["mix of base=%s with tint=%s" % (base, tint)]
    for label, value in rows:
        lines.append("%s : %s" % (label.rjust(width), value))
    return "\n".join(lines)


if __name__ == "__main__":
    base = 5.0
    tint = 1.2
    print(proportion(base, tint))
    print(describe_mix(base, tint))

