def _check_hours(name, value):
    numeric = (int, float)
    if not isinstance(value, numeric):
        raise TypeError("{0} hours must be numeric".format(name))
    if value <= 0:
        raise ValueError("{0} hours must be positive".format(name))


def validate_schedule(fasting, eating):
    _check_hours("fasting", fasting)
    _check_hours("eating", eating)
    total = fasting + eating
    if total > 24:
        raise ValueError("cycle of {0}h exceeds a day".format(total))
    return total


def cycle_duration(fasting, eating):
    return fasting + eating


def imbalance_metric(fasting, eating):
    return abs(fasting - 2 * eating)


def metabolic_score(fasting, eating):
    duration = cycle_duration(fasting, eating)
    return fasting * eating / duration


def autophagy_index(fasting, eating):
    imbalance = imbalance_metric(fasting, eating)
    duration = cycle_duration(fasting, eating)
    return imbalance ** 2 / duration


def score(fasting, eating):
    metabolic = metabolic_score(fasting, eating)
    autophagy = autophagy_index(fasting, eating)
    return metabolic + autophagy


def classify(total):
    if total < 4.0:
        return "gentle"
    if total < 6.0:
        return "moderate"
    if total < 9.0:
        return "aggressive"
    return "extreme"


def describe(fasting, eating):
    duration = validate_schedule(fasting, eating)
    total = score(fasting, eating)
    report = {}
    report["schedule"] = "{0}:{1}".format(fasting, eating)
    report["duration"] = duration
    report["imbalance"] = imbalance_metric(fasting, eating)
    report["metabolic"] = metabolic_score(fasting, eating)
    report["autophagy"] = autophagy_index(fasting, eating)
    report["total"] = total
    report["class"] = classify(total)
    return report


def format_report(report):
    header = "{0} ({1}h cycle)".format(report["schedule"], report["duration"])
    header = header + " -> " + report["class"]
    parts = [
        "imbalance={0}".format(report["imbalance"]),
        "metabolic={0}".format(report["metabolic"]),
        "autophagy={0}".format(report["autophagy"]),
        "total={0}".format(report["total"]),
    ]
    return header + "\n  " + ", ".join(parts)


def compare(schedules):
    reports = [describe(pair[0], pair[1]) for pair in schedules]
    reports.sort(key=lambda item: item["total"])
    return reports


if __name__ == "__main__":
    fasting = 16
    eating = 8
    print(score(fasting, eating))
    candidates = [
        (16, 8),
        (18, 6),
        (20, 4),
        (12, 12),
    ]
    for entry in compare(candidates):
        print(format_report(entry))

