from numbers import Real


def _check_width(label, value):
    if not isinstance(value, Real):
        raise TypeError("{} width must be numeric; got {}".format(label, type(value).__name__))
    if value <= 0:
        raise ValueError("{} width must be positive; got {}".format(label, value))


def _validate(original, target):
    _check_width("original", original)
    _check_width("target", target)


def average_width(original, target):
    _validate(original, target)
    return (original + target) / 2


def scaling_difference(original, target):
    _validate(original, target)
    return abs(original - target)


def pixel_density_factor(original, target):
    average = average_width(original, target)
    return (original * target) / average


def distortion_index(original, target):
    difference = scaling_difference(original, target)
    average = average_width(original, target)
    return (difference * difference) / average


def scale(original, target):
    density = pixel_density_factor(original, target)
    distortion = distortion_index(original, target)
    return density + distortion


def describe(original, target):
    parts = [
        "original={}".format(original),
        "target={}".format(target),
        "average={}".format(average_width(original, target)),
        "difference={}".format(scaling_difference(original, target)),
        "density={}".format(pixel_density_factor(original, target)),
        "distortion={}".format(distortion_index(original, target)),
        "scaled={}".format(scale(original, target)),
    ]
    return ", ".join(parts)


def scale_table(widths, target):
    rows = []
    for width in widths:
        value = scale(width, target)
        rows.append((width, value))
    return rows


def format_table(rows):
    lines = []
    for width, value in rows:
        lines.append("{:>8} -> {}".format(width, value))
    return "\n".join(lines)


COMMON_WIDTHS = (426, 640,
                 854, 1280,
                 1920, 3840)


if __name__ == "__main__":
    original = 1920
    target = 1280
    print(scale(original, target))
    print(describe(original, target))
    print(format_table(scale_table(COMMON_WIDTHS, target)))

