METRIC_ORDER = [
    "total",
    "overlap",
    "efficiency",
    "risk",
    "score",
]


def validate_duration(name, value):
    if not isinstance(value, NUMERIC_TYPES):
        raise TypeError("invalid {} duration type: {!r}".format(name, value))
    if value < 0:
        raise ValueError("negative {} duration: {}".format(name, value))


def validate_durations(intake, exhaust):
    validate_duration("intake", intake)
    validate_duration("exhaust", exhaust)
    if total_open_duration(intake, exhaust) == 0:
        raise ValueError("total open duration must be positive")


def total_open_duration(intake, exhaust):
    return intake + exhaust


def overlap_duration(intake, exhaust):
