NUMERIC = (int, float)


def bulk_weight(sand, clay):
    _validate(sand, clay)
    return sand + clay


def weight_disparity(sand, clay):
    _validate(sand, clay)
    return abs(sand - clay)


def drainage_coefficient(sand, clay):
    bulk = bulk_weight(sand, clay)
    return (sand * clay) / bulk


def compaction_index(sand, clay):
    disparity = weight_disparity(sand, clay)
    bulk = bulk_weight(sand, clay)
    return (disparity * disparity) / bulk


def _validate(sand, clay):
    labelled = (
        ("sand", sand),
        ("clay", clay),
    )
    for name, value in labelled:
        if not isinstance(value, NUMERIC):
            raise TypeError("non-numeric {0} weight: {1}".format(name, type(value).__name__))
        if value < 0:
            raise ValueError("negative {0} weight: {1}".format(name, value))
    if sand + clay == 0:
        raise ValueError("combined weight of sand and clay must be positive")


def assess(sand, clay):
    drainage = drainage_coefficient(sand, clay)
    compaction = compaction_index(sand, clay)
    return drainage + compaction


def texture_class(sand, clay):
    bands = (
        ("clay-heavy", 0.35),
        ("loam", 0.65),
        ("sandy", 0.85),
    )
    sand_share = sand / bulk_weight(sand, clay)
    for label, ceiling in bands:
        if sand_share <= ceiling:
            return label
    return "sand"


def metrics(sand, clay):
    return {
        "bulk": bulk_weight(sand, clay),
        "disparity": weight_disparity(sand, clay),
        "drainage": drainage_coefficient(sand, clay),
        "compaction": compaction_index(sand, clay),
        "score": assess(sand, clay),
        "texture": texture_class(sand, clay),
