NUMBER_TYPES = (int, float)


def validate_breath(inhale, exhale):
    for value in (inhale, exhale):
        if not isinstance(value, NUMBER_TYPES):
            raise TypeError("breath length must be a number, got {}".format(type(value).__name__))
        if value <= 0:
            raise ValueError("breath length must be positive, got {}".format(value))


def total_duration(inhale, exhale):
    validate_breath(inhale, exhale)
    return inhale + exhale


def retention_gap(inhale, exhale):
    validate_breath(inhale, exhale)
    return abs(inhale - exhale)


def oxygenation_factor(inhale, exhale):
    total = total_duration(inhale, exhale)
    return (inhale * exhale) / total


def relaxation_index(inhale, exhale):
    gap = retention_gap(inhale, exhale)
    total = total_duration(inhale, exhale)
    return (gap * gap) / total


def measure(inhale, exhale):
    oxygen = oxygenation_factor(inhale, exhale)
    relaxation = relaxation_index(inhale, exhale)
    return oxygen + relaxation


def breath_report(inhale, exhale):
    labels = [
        "total duration",
        "retention gap",
        "oxygenation factor",
        "relaxation index",
        "breath score",
    ]
    values = [
        total_duration(inhale, exhale),
        retention_gap(inhale, exhale),
        oxygenation_factor(inhale, exhale),
        relaxation_index(inhale, exhale),
        measure(inhale, exhale),
    ]
    lines = []
    for label, value in zip(labels, values):
        lines.append("{}: {}".format(label, value))
    return "\n".join(lines)


def compare_patterns(patterns):
    scored = []
    for inhale, exhale in patterns:
        score = measure(inhale, exhale)
        scored.append((score, inhale, exhale))
    scored.sort(key=lambda item: item[0])
    return scored


def format_ranking(scored):
    rows = []
    ranked = enumerate(scored, start=1)
    for position, entry in ranked:
        score, inhale, exhale = entry
        pattern = "{}s in / {}s out".format(inhale, exhale)
        rows.append("{}. {} -> {}".format(position, pattern, score))
    return "\n".join(rows)


if __name__ == "__main__":
    inhale = 4
    exhale = 6
    print(measure(inhale, exhale))
    print(breath_report(inhale, exhale))
    candidates = [
        (4, 6),
        (5, 5),
        (3, 9),
        (6, 2),
        (7, 7),
    ]
    print(format_ranking(compare_patterns(candidates)))

