NUMERIC_TYPES = (int, float)


def _validate_speeds(wind, boat):
    labels = ["wind", "boat"]
    values = [wind, boat]
    for label, value in zip(labels, values):
        if not isinstance(value, NUMERIC_TYPES):
            raise TypeError("{} speed must be numeric".format(label))
        if value < 0:
            raise ValueError("{} speed must not be negative".format(label))


def relative_speed_sum(wind, boat):
    _validate_speeds(wind, boat)
    return wind + boat


def speed_deficit(wind, boat):
    _validate_speeds(wind, boat)
    return abs(wind - boat)


def sail_drive_factor(wind, boat):
    total = relative_speed_sum(wind, boat)
    if total == 0:
        return 0.0
    return (wind * boat) / total


def drag_penalty_index(wind, boat):
    deficit = speed_deficit(wind, boat)
    total = relative_speed_sum(wind, boat)
    if total == 0:
        return 0.0
    return (deficit * deficit) / total


def vector(wind, boat):
    drive = sail_drive_factor(wind, boat)
    penalty = drag_penalty_index(wind, boat)
    return drive + penalty


def performance_rows(wind, boat):
    total = relative_speed_sum(wind, boat)
    deficit = speed_deficit(wind, boat)
    drive = sail_drive_factor(wind, boat)
    penalty = drag_penalty_index(wind, boat)
    overall = vector(wind, boat)
    return [
