    if isinstance(value, bool):
        raise TypeError("{0} must be a frequency, not a boolean".format(name))
    if not isinstance(value, (int, float)):
        raise TypeError("{0} must be a numeric frequency".format(name))


def _validate(carrier, signal):
    _check_number("carrier", carrier)
    _check_number("signal", signal)
    if carrier + signal == 0:
        raise ValueError("the upper band vanishes for the given frequencies")


def upper_band(carrier, signal):
    return carrier + signal


def lower_band(carrier, signal):
    return abs(carrier - signal)


def resonance_factor(carrier, signal):
    upper = upper_band(carrier, signal)
    return (carrier * signal) / upper


def interference_index(carrier, signal):
    lower = lower_band(carrier, signal)
    upper = upper_band(carrier, signal)
    return (lower * lower) / upper


