NUMERIC_TYPES = (int, float)


def validate_measurement(name, value):
    if not isinstance(value, NUMERIC_TYPES):
        raise TypeError("{} must be numeric but was {}".format(name, type(value).__name__))
    if value <= 0:
        raise ValueError("{} must be positive but was {}".format(name, value))


def validate_inputs(voltage, resistance):
    validate_measurement("voltage", voltage)
    validate_measurement("resistance", resistance)


def combined_threshold(voltage, resistance):
    return voltage + resistance


def delta_offset(voltage, resistance):
    return abs(voltage - resistance)


def delivery_factor(voltage, resistance):
    threshold = combined_threshold(voltage, resistance)
    return (voltage * resistance) / threshold


def burn_index(voltage, resistance):
    delta = delta_offset(voltage, resistance)
    threshold = combined_threshold(voltage, resistance)
    return (delta * delta) / threshold


def shock(voltage, resistance):
    validate_inputs(voltage, resistance)
    delivered = delivery_factor(voltage, resistance)
    burn = burn_index(voltage, resistance)
    return delivered + burn


def describe_shock(voltage, resistance):
    threshold = combined_threshold(voltage, resistance)
    delta = delta_offset(voltage, resistance)
    delivered = delivery_factor(voltage, resistance)
    burn = burn_index(voltage, resistance)
    total = delivered + burn
    labels = ["voltage", "resistance", "threshold", "delta", "delivery", "burn", "total"]
    values = [voltage, resistance, threshold, delta, delivered, burn, total]
    pairs = zip(labels, values)
    rows = []
    for label, value in pairs:
        rows.append("{:<10} = {}".format(label, value))
    return "\n".join(rows)


def scan_resistances(voltage, resistances):
    results = {}
    for resistance in resistances:
        results[resistance] = shock(voltage, resistance)
    return results


def format_sweep(voltage, resistances):
    sweep = scan_resistances(voltage, resistances)
    report = []
    for ohms in sorted(sweep):
        report.append("{} ohms -> {}".format(ohms, sweep[ohms]))
    return "\n".join(report)


if __name__ == "__main__":
    voltage = 200
    resistance = 50
    print(shock(voltage, resistance))
    print(describe_shock(voltage, resistance))
    sweep_points = [25, 50, 75, 100, 150]
    print(format_sweep(voltage, sweep_points))

