def _validate_time(label, value):
    if not isinstance(value, NUMERIC_TYPES):
        raise TypeError("{} must be numeric, got {}".format(label, type(value).__name__))
    if value < 0:
        raise ValueError("{} must not be negative, got {}".format(label, value))
    return float(value)


def validate_times(retention, mobile):
    retention = _validate_time("retention", retention)
    mobile = _validate_time("mobile", mobile)
    if total_flow_duration(retention, mobile) == 0:
        raise ValueError("retention and mobile times cannot both be zero")
    return {"retention": retention, "mobile": mobile}


def total_flow_duration(retention, mobile):
    return retention + mobile


def separation_delay(retention, mobile):
    return abs(retention - mobile)


def column_resolution_factor(retention, mobile):
    total = total_flow_duration(retention, mobile)
    return (retention * mobile) / total


def peak_broadening_index(retention, mobile):
    delay = separation_delay(retention, mobile)
    total = total_flow_duration(retention, mobile)
    return (delay * delay) / total


def resolve(retention, mobile):
    times = validate_times(retention, mobile)
    clean_retention = times["retention"]
    clean_mobile = times["mobile"]
    factor = column_resolution_factor(clean_retention, clean_mobile)
    index = peak_broadening_index(clean_retention, clean_mobile)
    return factor + index


def summarize(retention, mobile):
    times = validate_times(retention, mobile)
    clean_retention = times["retention"]
    clean_mobile = times["mobile"]
    metrics = {}
    metrics["total"] = total_flow_duration(clean_retention, clean_mobile)
    metrics["delay"] = separation_delay(clean_retention, clean_mobile)
    metrics["factor"] = column_resolution_factor(clean_retention, clean_mobile)
    metrics["index"] = peak_broadening_index(clean_retention, clean_mobile)
    metrics["score"] = resolve(clean_retention, clean_mobile)
    return metrics


def format_report(metrics):
    rows = [
        ("Total flow duration", "total"),
        ("Separation delay", "delay"),
        ("Column resolution factor", "factor"),
        ("Peak broadening index", "index"),
        ("Combined score", "score"),
    ]
    lines = []
    for label, key in rows:
        lines.append("{:<26}{}".format(label + ":", metrics[key]))
    return "\n".join(lines)


if __name__ == "__main__":
    retention = 12.4
    mobile = 2.1
    print(resolve(retention, mobile))
    print(format_report(summarize(retention, mobile)))

