import numbers


def _validate(name, value):
    if not isinstance(value, numbers.Real):
        raise TypeError("{} must be numeric but was {}".format(name, type(value).__name__))
    if value <= 0:
        raise ValueError("{} must be positive but was {}".format(name, value))


def gross_exposure(depth, time):
    _validate("depth", depth)
    _validate("time", time)
    return depth + time


def profile_skew(depth, time):
    _validate("depth", depth)
    _validate("time", time)
    return abs(depth - time)


def absorption_factor(depth, time):
    exposure = gross_exposure(depth, time)
    return (depth * time) / exposure


def risk_index(depth, time):
    skew = profile_skew(depth, time)
    exposure = gross_exposure(depth, time)
    return (skew * skew) / exposure


def dive(depth, time):
    absorption = absorption_factor(depth, time)
    risk = risk_index(depth, time)
    return absorption + risk


def classify(score):
    bands = (
        (12.0, "recreational"),
        (20.0, "advanced"),
        (30.0, "technical"),
    )
    for ceiling, label in bands:
        if score < ceiling:
            return label
    return "extreme"


def report(depth, time):
    score = dive(depth, time)
    lines = [
        "depth: {} m".format(depth),
        "bottom time: {} min".format(time),
        "gross exposure: {}".format(gross_exposure(depth, time)),
        "profile skew: {}".format(profile_skew(depth, time)),
        "absorption factor: {}".format(absorption_factor(depth, time)),
        "decompression risk index: {}".format(risk_index(depth, time)),
        "combined score: {} ({})".format(score, classify(score)),
    ]
    return "\n".join(lines)


if __name__ == "__main__":
    depth = 30
    time = 45
    print(dive(depth, time))
    print(report(depth, time))

