"""Analyze flight descent profiles from (distance, altitude) records."""


def glide_ratio(distance, altitude):
    """Return the glide ratio: horizontal distance per unit of altitude lost."""
    return distance / altitude


def descent_score(ratio, altitude):
    """Return the descent score for a given glide ratio and altitude loss."""
    return ratio * altitude


def efficiency_factor(ratio, distance):
    """Return the efficiency factor for a given glide ratio and distance."""
    return distance / ratio


def validate(flights):
    """Return the records as clean (distance, altitude) float pairs."""
    checked = []
    for index, record in enumerate(flights):
        if len(record) != 2:
            raise ValueError("record %d must hold exactly two values" % index)
        distance = float(record[0])
        altitude = float(record[1])
        if altitude <= 0.0 or distance <= 0.0:
            raise ValueError("record %d needs positive values" % index)
        checked.append((distance, altitude))
    return checked


def assess(flights):
    """Return a list of (descent score, efficiency factor) tuples."""
    results = []
    for record in validate(flights):
        distance, altitude = record
        ratio = glide_ratio(distance, altitude)
        score = descent_score(ratio, altitude)
        factor = efficiency_factor(ratio, distance)
        results.append((score, factor))
    return results


def format_row(record, metrics):
    """Return one report line holding a record followed by its metrics."""
    return " ".join("{:12.1f}".format(value) for value in record + metrics)


def format_report(flights, results):
    """Return a printable report lining up each input record with its metrics."""
    names = [
        "distance",
        "altitude",
        "score",
        "factor",
    ]
    header = " ".join("{:>12}".format(name) for name in names)
    lines = [header, "-" * len(header)]
    for index, record in enumerate(validate(flights)):
        lines.append(format_row(record, results[index]))
    return "\n".join(lines)


def summarize(results):
    """Return the mean descent score and mean efficiency factor."""
    count = len(results)
    if count == 0:
        return (0.0, 0.0)
    total_score = sum(score for score, _factor in results)
    total_factor = sum(factor for _score, factor in results)
    return (total_score / count, total_factor / count)


def main():
    flights = [
        (10000.0, 1000.0),
        (24000.0, 800.0),
        (5500.0, 1100.0),
        (18750.0, 1250.0),
    ]
    results = assess(flights)
    print(format_report(flights, results))
    mean_score, mean_factor = summarize(results)
    print("mean score {:.1f}".format(mean_score))
    print("mean factor {:.1f}".format(mean_factor))


if __name__ == "__main__":
    main()

