import math

NUMERIC_TYPES = (int, float)
PAIR_TYPES = (tuple, list)


def compute_speed(megabytes, seconds):
    if seconds <= 0:
        raise ValueError("elapsed seconds must be positive")
    return megabytes / seconds


def compute_stability(speed, seconds):
    return speed * math.sqrt(seconds)


def estimate_minutes(speed, megabytes):
    if speed <= 0:
        raise ValueError("speed must be positive to estimate a transfer")
    return (1000.0 / speed) / 60.0


def truncate(value, places):
    factor = 10.0 ** places
    return math.floor(value * factor) / factor


def validate_record(record, position):
    if not isinstance(record, PAIR_TYPES):
        raise TypeError("record %d must be a pair of numbers" % position)
    if len(record) != 2:
        raise ValueError("record %d must hold exactly two values" % position)
    for value in record:
        if not isinstance(value, NUMERIC_TYPES):
            raise TypeError("record %d contains a non numeric value" % position)
    if record[0] <= 0:
        raise ValueError("record %d must transfer some megabytes" % position)
    return tuple(record)


def benchmark(downloads):
    results = []
    for position in range(len(downloads)):
        megabytes, seconds = validate_record(downloads[position], position)
        speed = compute_speed(megabytes, seconds)
        stability = compute_stability(speed, seconds)
        minutes = estimate_minutes(speed, megabytes)
        rounded_stability = truncate(stability, 2)
        rounded_minutes = truncate(minutes, 2)
        results.append((rounded_stability, rounded_minutes))
    return results


def format_report(downloads, results):
    header = "%8s | %8s | %10s | %8s" % ("MB", "seconds", "stability", "minutes")
    lines = [header, "-" * len(header)]
    for record, metrics in zip(downloads, results):
        values = (record[0], record[1], metrics[0], metrics[1])
        lines.append("%8.1f | %8.1f | %10.2f | %8.2f" % values)
    return "\n".join(lines)


def main():
    downloads = [
        (500.0, 50.0),
        (1200.0, 90.0),
        (64.0, 8.0),
        (2048.0, 120.0),
    ]
    results = benchmark(downloads)
    print(format_report(downloads, results))
    print("metrics:", results)


if __name__ == "__main__":
    main()

