def _validate(occupied, total):
    """Reject records that cannot describe a real storage zone."""
    if not isinstance(occupied, int):
        raise TypeError("occupied slots must be an int: {!r}".format(occupied))
    if not isinstance(total, int):
        raise TypeError("total slots must be an int: {!r}".format(total))
    if total <= 0:
        raise ValueError("total slots must be positive: {}".format(total))
    if occupied < 0:
        raise ValueError("occupied slots must not be negative: {}".format(occupied))
    if occupied > total:
        raise ValueError("occupied {} exceeds total {}".format(occupied, total))


def vacant_slots(occupied, total):
    """Number of shelf slots still free in the zone."""
    _validate(occupied, total)
    return total - occupied


def vacancy_percentage(vacant, total):
    """Share of the zone that is still free, as a fraction of the total."""
    return vacant / total


def expansion_index(vacant, occupied):
    """How many times the occupied stock fits into the remaining space."""
    if vacant == 0:
        return float("inf")
    return occupied / vacant


def audit(zones):
    """Compute (vacancy, expansion index) for each (occupied, total) record."""
    results = []
    for record in zones:
        occupied, total = record
        vacant = vacant_slots(occupied, total)
        percentage = vacancy_percentage(vacant, total)
        index = expansion_index(vacant, occupied)
        results.append((percentage, index))
    return results


def format_report(zones, results):
    """Render the audit as aligned text rows, one per zone."""
    header = "{:<6}{:>10}".format("zone", "occupied")
    header += "{:>12}{:>12}".format("vacancy", "index")
    lines = [header, "-" * len(header)]
    for number, record in enumerate(zones):
        occupied, total = record
        percentage, index = results[number]
        stock = "{}/{}".format(occupied, total)
        row = "{:<6}{:>10}".format(number + 1, stock)
        row += "{:>11.1f}%{:>12.2f}".format(percentage * 100, index)
        lines.append(row)
    return "\n".join(lines)


def main():
    zones = [
        (800, 1000),
        (250, 400),
        (0, 120),
        (500, 500),
    ]
    results = audit(zones)
    print(format_report(zones, results))
    crowded = []
    for number, metrics in enumerate(results):
        if metrics[0] < 0.1:
            crowded.append(number + 1)
    print("zones needing attention: {}".format(crowded))


if __name__ == "__main__":
    main()

