NUMERIC_TYPES = (int, float)


def compute_pitch(length, threads):
    """Pitch in millimetres: measured length divided by the thread count."""
    return length / threads


def compute_grip(pitch, threads):
    """Grip strength proxy: pitch multiplied by the square of the thread count."""
    return pitch * threads * threads


def compute_tolerance(pitch, length):
    """Tolerance grade: pitch divided by the measured length."""
    return pitch / length


def validate_record(record):
    """Return (threads, length) after checking the record is a usable pair."""
    try:
        threads, length = record
    except (TypeError, ValueError):
        raise ValueError("each record must be a pair of (threads, length)")
    if isinstance(threads, bool):
        raise TypeError("thread count must be an integer")
    if not isinstance(threads, int):
        raise TypeError("thread count must be an integer")
    if threads <= 0:
        raise ValueError("thread count must be positive")
    if not isinstance(length, NUMERIC_TYPES):
        raise TypeError("measured length must be numeric")
    if length <= 0:
        raise ValueError("measured length must be positive")
    return threads, float(length)


def inspect(screws):
    """Compute (grip, tolerance) metrics for every screw or bolt record."""
    metrics = []
    for record in screws:
        threads, length = validate_record(record)
        pitch = compute_pitch(length, threads)
        grip = compute_grip(pitch, threads)
        tolerance = compute_tolerance(pitch, length)
        metrics.append((grip, tolerance))
    return metrics


def format_report(screws, metrics):
    """Build a plain text table lining records up with their computed metrics."""
    header = "{:>8} {:>10} {:>12} {:>12}"
    lines = [header.format("threads", "length", "grip", "tolerance")]
    lines.append("-" * len(lines[0]))
    row = "{:>8d} {:>10.3f} {:>12.4f} {:>12.6f}"
    for record, result in zip(screws, metrics):
        threads, length = record
        grip, tolerance = result
        lines.append(row.format(threads, length, grip, tolerance))
    return "\n".join(lines)


def summarise(metrics):
    """Return the mean grip and the widest tolerance spread of an inspection run."""
    if not metrics:
        return 0.0, 0.0
    grips = [grip for grip, _tolerance in metrics]
    tolerances = [tolerance for _grip, tolerance in metrics]
    return sum(grips) / len(grips), max(tolerances) - min(tolerances)


def main():
    batch = [
        (20, 10.0),
        (8, 12.5),
        (32, 48.0),
        (5, 3.25),
    ]
    metrics = inspect(batch)
    print(format_report(batch, metrics))
    mean_grip, tolerance_spread = summarise(metrics)
    print("\nmean grip: {:.4f}".format(mean_grip))
    print("tolerance spread: {:.6f}".format(tolerance_spread))


if __name__ == "__main__":
    main()

