NUMERIC = (int, float)


def _validate(items, hours):
    """Reject records that cannot produce a meaningful rate."""
    if not isinstance(items, NUMERIC):
        raise TypeError("items must be a number, got {!r}".format(items))
    if not isinstance(hours, NUMERIC):
        raise TypeError("hours must be a number, got {!r}".format(hours))
    if hours <= 0:
        raise ValueError("hours must be positive: {!r}".format(hours))
    if items < 0:
        raise ValueError("items must not be negative: {!r}".format(items))


def production_rate(items, hours):
    """Items produced per hour worked."""
