import numbers


def velocity_severity(amplitude, frequency):
    """Velocity severity is the product of peak amplitude and dominant frequency."""
    return amplitude * frequency


def acceleration_stress(severity, frequency):
    """Acceleration stress scales the severity by the frequency once more."""
    return severity * frequency


def danger_threshold(severity, amplitude):
    """Danger threshold is a tenth of the severity offset by the raw amplitude."""
    return severity / 10.0 + amplitude


def validate_sensors(sensors):
    """Return the sensor records as a list of clean (amplitude, frequency) pairs."""
    cleaned = []
    for index, record in enumerate(sensors):
        if len(record) != 2:
            raise ValueError("record {} must hold exactly two values".format(index))
        amplitude, frequency = record
        fields = (
            ("amplitude", amplitude),
            ("frequency", frequency),
        )
        for name, value in fields:
            if not isinstance(value, numbers.Real):
                raise TypeError("record {} has a non-numeric {}".format(index, name))
            if value < 0:
                raise ValueError("record {} has a negative {}".format(index, name))
        cleaned.append((float(amplitude), float(frequency)))
    return cleaned


def classify(stress, threshold):
    """Label a machine from its acceleration stress and danger threshold."""
    if stress > 10000.0 or threshold > 50.0:
        return "CRITICAL"
    if stress > 2000.0:
        return "WARNING"
    return "NORMAL"


def diagnose(sensors):
    results = []
    for record in validate_sensors(sensors):
        amplitude, frequency = record
        severity = velocity_severity(amplitude, frequency)
        stress = acceleration_stress(severity, frequency)
        threshold = danger_threshold(severity, amplitude)
        results.append((stress, threshold))
    return results


def format_report(sensors, results):
    row = "{:>10} {:>10} {:>14} {:>12} {:>10}"
    lines = [row.format("ampl", "freq", "stress", "threshold", "status")]
    data = "{:>10.2f} {:>10.2f} {:>14.2f} {:>12.2f} {:>10}"
    for index, record in enumerate(sensors):
        amplitude, frequency = record
        stress, threshold = results[index]
        lines.append(data.format(
            amplitude,
            frequency,
            stress,
            threshold,
            classify(stress, threshold)))
    return "\n".join(lines)


def main():
    readings = [
        (2.0, 50.0),
        (0.5, 120.0),
        (7.5, 30.0),
        (1.0, 10.0),
        (12.0, 95.0),
    ]
    metrics = diagnose(readings)
    print(format_report(readings, metrics))
    critical = 0
    for stress, threshold in metrics:
        if classify(stress, threshold) == "CRITICAL":
            critical += 1
    print("machines needing immediate service: {} of {}".format(critical, len(readings)))


if __name__ == "__main__":
    main()

