"""Certification helpers for particulate filtration units."""

GRADE_TABLE = (
    (0.99, "premium"),
    (0.95, "standard"),
    (0.90, "utility"),
)

ROW_TEMPLATE = "{:>4}{:>8}{:>8}{:>7}{:>9}  {}"


def particles_removed(input_count, output_count):
    """Number of particles trapped by the unit."""
    return input_count - output_count


def filtration_efficiency(removed, input_count):
    """Fraction of the incoming particulate load that was captured."""
    if input_count <= 0:
        raise ValueError("input particulate count must be positive")
    return round(removed / input_count, 2)


def lifespan_penalty(removed, output_count):
    """Leakage relative to the captured load; high values shorten service life."""
    if removed <= 0:
        raise ValueError("a unit that removes nothing cannot be certified")
    return round(output_count / removed, 2)


def validate_record(record):
    """Check one (input, output) pair and return it as plain integers."""
    if len(record) != 2:
        raise ValueError("each record must contain exactly two counts")
    for value in record:
        if not isinstance(value, int):
            raise TypeError("particulate counts must be integers")
        if value < 0:
            raise ValueError("particulate counts cannot be negative")
    input_count, output_count = record
    if output_count > input_count:
        raise ValueError("output count cannot exceed input count")
    return input_count, output_count


def certify(filters):
    """Return a list of (efficiency, lifespan penalty) tuples, one per unit."""
    results = []
    for record in filters:
        input_count, output_count = validate_record(record)
        removed = particles_removed(input_count, output_count)
        efficiency = filtration_efficiency(removed, input_count)
        penalty = lifespan_penalty(removed, output_count)
        results.append((efficiency, penalty))
    return results


def grade_of(efficiency):
    """Map an efficiency figure onto a certification grade."""
    for threshold, label in GRADE_TABLE:
        if efficiency >= threshold:
            return label
    return "rejected"


def format_report(filters, metrics):
    """Build a printable certification table."""
    lines = ["unit   input  output    eff  penalty  grade"]
    for index, record in enumerate(filters):
        efficiency, penalty = metrics[index]
        row = ROW_TEMPLATE.format(
            index + 1,
            record[0],
            record[1],
            efficiency,
            penalty,
            grade_of(efficiency),
        )
        lines.append(row)
    return "\n".join(lines)


def main():
    units = [
        (10000, 100),
        (20000, 400),
        (8000, 800),
        (15000, 30),
    ]
    metrics = certify(units)
    print(format_report(units, metrics))
    print("raw metrics:", metrics)


if __name__ == "__main__":
    main()

