STANDARD_SPEED = 1000.0


def bytes_saved(original, compressed):
    """Return how many bytes the compression removed."""
    return original - compressed


def compression_ratio(saved, original):
    """Return the saved bytes as a fraction of the original size."""
    if original <= 0:
        return 0.0
    return saved / original


def time_reduction(saved, compressed):
    """Return the seconds no longer spent transmitting the archive."""
    return saved / STANDARD_SPEED


def validate_archive(original, compressed):
    labelled = [
        ("original", original),
        ("compressed", compressed),
    ]
    for label, value in labelled:
        if not isinstance(value, int):
            raise TypeError(f"{label} size must be an integer: {value!r}")
        if value < 0:
            raise ValueError(f"{label} size must not be negative: {value}")
    if compressed > original:
        raise ValueError(f"compressed size {compressed} exceeds original {original}")


