def delay_per_floor(wait, floors):
    """Average seconds of waiting attributable to each floor travelled."""
    if floors <= 0:
        raise ValueError("floors travelled must be positive, got %r" % (floors,))
    return wait / floors


def frustration_index(delay, wait):
    """Passenger annoyance grows with both the delay and the total wait."""
    return delay * wait


def efficiency_score(delay, floors):
    """A perfect trip scores 100; every wasted second costs a point."""
    return 100.0 - delay * floors


def validate_trip(record):
    """Normalise one raw record into a (floors, wait) pair of numbers."""
    if len(record) != 2:
        raise ValueError("expected a (floors, wait) pair, got %r" % (record,))
    floors, wait = record
    if not isinstance(floors, (int, float)):
        raise TypeError("floors must be numeric, got %r" % (floors,))
    if not isinstance(wait, (int, float)):
        raise TypeError("wait must be numeric, got %r" % (wait,))
    if wait < 0:
        raise ValueError("wait must not be negative, got %r" % (wait,))
    return floors, float(wait)


def audit(trips):
    """Return a (frustration, efficiency) tuple for every trip supplied."""
    results = []
    for record in trips:
        floors, wait = validate_trip(record)
        delay = delay_per_floor(wait, floors)
        frustration = frustration_index(delay, wait)
        efficiency = efficiency_score(delay, floors)
        results.append((frustration, efficiency))
    return results


def format_row(index, floors, wait, frustration, efficiency):
    """Render a single audited trip as a fixed-width table row."""
    return "%3d | %6d | %7.1f | %10.1f | %7.1f" % (
        index, floors, wait, frustration, efficiency,
    )


def report(trips):
    """Build a human readable audit table plus a summary line."""
    audited = audit(trips)
    header = "%3s | %6s | %7s | %10s | %7s" % (
        "#", "floors", "wait", "frustrate", "score",
    )
    rule = "-" * len(header)
    lines = [header, rule]
    for index, record in enumerate(audited):
        floors, wait = validate_trip(trips[index])
        frustration, efficiency = record
        row = format_row(index + 1, floors, wait, frustration, efficiency)
        lines.append(row)
    worst = max(audited, key=lambda pair: pair[0])
    average = sum(pair[1] for pair in audited) / len(audited)
    lines.append(rule)
    lines.append("worst frustration %.1f, mean score %.1f" % (worst[0], average))
    return "\n".join(lines)


def main():
    trips = [
        (5, 30.0),
        (12, 18.0),
        (3, 45.0),
        (20, 20.0),
        (8, 4.0),
    ]
    print(report(trips))


if __name__ == "__main__":
    main()

