TANK_CAPACITY = 15.0
PRICE_PER_GALLON = 3.0


def miles_per_gallon(miles, gallons):
    if gallons <= 0:
        raise ValueError("gallons must be positive, got {!r}".format(gallons))
    return miles / gallons


def full_tank_range(mileage, gallons):
    if mileage <= 0 or gallons <= 0:
        raise ValueError("mileage and gallons must both be positive")
    return mileage * TANK_CAPACITY


def fuel_cost(mileage, miles):
    if mileage <= 0:
        raise ValueError("mileage must be positive, got {!r}".format(mileage))
    return miles / mileage * PRICE_PER_GALLON


def validate_trip(trip):
    if len(trip) != 2:
        raise ValueError("each trip needs exactly two values: miles, gallons")
    miles = float(trip[0])
    gallons = float(trip[1])
    if miles < 0:
        raise ValueError("miles cannot be negative, got {!r}".format(miles))
    return miles, gallons


def analyze(trips):
    results = []
    for trip in trips:
        miles, gallons = validate_trip(trip)
        mileage = miles_per_gallon(miles, gallons)
        est_range = full_tank_range(mileage, gallons)
        cost = fuel_cost(mileage, miles)
        results.append((est_range, cost))
    return results


def format_report(trips, metrics):
    header = "{:>10} {:>10}".format("miles", "gallons")
    header += "{:>12} {:>10}".format("range", "cost")
    lines = [header]
    for index in range(len(metrics)):
        miles, gallons = trips[index]
        est_range, cost = metrics[index]
        row = "{:>10.1f} {:>10.1f}".format(miles, gallons)
        row += "{:>12.1f} {:>10.2f}".format(est_range, cost)
        lines.append(row)
    return "\n".join(lines)


def summarize(metrics):
    if not metrics:
        return 0.0, 0.0
    ranges = [entry[0] for entry in metrics]
    costs = [entry[1] for entry in metrics]
    return sum(ranges) / len(ranges), sum(costs)


def main():
    trips = [
        (300.0, 10.0),
        (120.5, 4.0),
        (450.0, 12.5),
        (88.0, 3.2),
    ]
    metrics = analyze(trips)
    print(metrics)
    print(format_report(trips, metrics))
    avg_range, total_cost = summarize(metrics)
    print("average range: {:.1f} miles".format(avg_range))
    print("total cost: ${:.2f}".format(total_cost))


if __name__ == "__main__":
    main()

