import math


NUMERIC_TYPES = (int, float)
SEQUENCE_TYPES = (list, tuple)


def _validate_point(point):
    if not isinstance(point, SEQUENCE_TYPES):
        raise TypeError("each data point must be a list of two numbers")
    if len(point) != 2:
        raise ValueError("each data point must contain exactly two values")
    for value in point:
        if not isinstance(value, NUMERIC_TYPES):
            raise TypeError("cylinder radius and stroke length must be numeric")
    return float(point[0]), float(point[1])


def displacement_diagonal(cylinder_radius, stroke_length):
    return math.hypot(cylinder_radius, stroke_length)


def stroke_bias(cylinder_radius, stroke_length):
    return math.copysign(cylinder_radius, stroke_length)


def peak_compression_ratio(diagonal, bias):
    return max(diagonal, bias)


def exhaust_vacuum_limit(diagonal, bias):
    return min(diagonal, bias)


def evaluate(pistons):
    results = []
    for point in pistons:
        cylinder_radius, stroke_length = _validate_point(point)
        diagonal = displacement_diagonal(cylinder_radius, stroke_length)
        bias = stroke_bias(cylinder_radius, stroke_length)
        compression = peak_compression_ratio(diagonal, bias)
        vacuum = exhaust_vacuum_limit(diagonal, bias)
        rounded_compression = round(compression, 2)
        rounded_vacuum = round(vacuum, 2)
        results.append((rounded_compression, rounded_vacuum))
        results.append((diagonal, bias))
    return results


def format_report(label, bounds):
    pieces = []
    for compression, vacuum in bounds:
        pieces.append("compression={0} vacuum={1}".format(compression, vacuum))
    return "{0}: {1}".format(label, " | ".join(pieces))


def main():
    nominal_cylinder = [[5.0, 12.0]]
    reversed_cylinder = [[8.0, -15.0]]
    compact_cylinder = [[3, 4]]
    datasets = [
        ("nominal", nominal_cylinder),
        ("reversed", reversed_cylinder),
        ("compact", compact_cylinder),
    ]
    for label, dataset in datasets:
        bounds = evaluate(dataset)
        print(bounds)
        print(format_report(label, bounds))


if __name__ == "__main__":
    main()

