import math


def validate(point):
    if not isinstance(point, list):
        raise TypeError("each data point must be a list of [height, elevation]")
    if len(point) != 2:
        raise ValueError("each data point needs exactly two values")
    height, elevation = point
    if height <= 0 or height == 1.0:
        raise ValueError("gnomon height must be positive and different from 1")
    if elevation <= 0:
        raise ValueError("sun elevation must be positive")
    return float(height), float(elevation)


def calculate(shadows):
    results = []
    for point in shadows:
        height, elevation = validate(point)
        summer_reach = math.pow(height, elevation)
        winter_decay = math.log(elevation, height)
        maximum_bound = max(summer_reach, winter_decay)
        minimum_bound = min(summer_reach, winter_decay)
        rounded_maximum = round(maximum_bound, 4)
        rounded_minimum = round(minimum_bound, 4)
        results.append((rounded_maximum, rounded_minimum))
        results.append((summer_reach, winter_decay))
    return results


def describe_point(point):
    height, elevation = validate(point)
    return "gnomon {0:g} at elevation {1:g}".format(height, elevation)


def format_results(dataset, results):
    lines = [describe_point(dataset[0])]
    for bounds in results:
        upper, lower = bounds
        lines.append("  max={0!r}, min={1!r}".format(upper, lower))
    return "\n".join(lines)


def main():
    noon_dataset = [[2.0, 4.0]]
    equinox_dataset = [[3.0, 9.0]]
    dusk_dataset = [[1.5, 0.5]]
    runs = [
        ("noon", noon_dataset),
