import math

NUMERIC_TYPES = (int,float)


def validate_point(point):
    if len(point) != 2:
        raise ValueError("each stroke point needs an inboard and an outboard length")
    inboard,outboard = point
    for value in (inboard,outboard):
        if not isinstance(value,NUMERIC_TYPES):
            raise TypeError("oar lengths must be numeric")
        if value <= 0:
            raise ValueError("oar lengths must be positive")
    return float(inboard),float(outboard)


def pivot_metrics(inboard,outboard):
    return {
        "pivot": math.hypot(inboard,outboard),
        "angle": math.atan2(outboard,inboard),
    }


def process(strokes):
    results = []
    for point in strokes:
        inboard,outboard = validate_point(point)
        metrics = pivot_metrics(inboard,outboard)
        pivot_vector = metrics["pivot"]
        catch_angle = metrics["angle"]
        max_stroke_force = max(pivot_vector,catch_angle)
        recovery_glide_limit = min(pivot_vector,catch_angle)
        rounded_force = round(max_stroke_force,3)
        rounded_glide = round(recovery_glide_limit,3)
        results.append((rounded_force,rounded_glide))
        results.append((pivot_vector,catch_angle))
    return results


def gearing_ratio(point):
    inboard,outboard = validate_point(point)
    return outboard / inboard


def describe_dataset(label,dataset):
    lines = ["{0} ({1} point(s))".format(label,len(dataset))]
    for point in dataset:
        inboard,outboard = validate_point(point)
        lines.append(
            "  inboard={0:.1f} outboard={1:.1f} gearing={2:.3f}".format(
                inboard,
                outboard,
                gearing_ratio(point),
            )
        )
    for index,entry in enumerate(process(dataset)):
        kind = "rounded" if index % 2 == 0 else "raw"
        lines.append("  {0}: {1}".format(kind,entry))
    return "\n".join(lines)


