import math

NUMERIC_TYPES = (int, float)
VALUE_LABELS = ("draw length", "band thickness")


def validate(point):
    if len(point) != 2:
        raise ValueError("each shot needs a draw length, a band thickness")
    for index in range(2):
        value = point[index]
        if not isinstance(value, NUMERIC_TYPES):
            raise TypeError("{} must be numeric".format(VALUE_LABELS[index]))
    draw, thickness = point
    return float(draw), float(thickness)


def snapback_diagonal(draw, thickness):
    return math.hypot(draw, thickness)


def tension_bias(draw, thickness):
    return math.copysign(draw, thickness)


def peak_velocity(diagonal, bias):
    return max(diagonal, bias)


def wear_limit(diagonal, bias):
    return min(diagonal, bias)


def process(shots):
    results = []
    for point in shots:
        draw, thickness = validate(point)
        diagonal = snapback_diagonal(draw, thickness)
        bias = tension_bias(draw, thickness)
        peak = peak_velocity(diagonal, bias)
        limit = wear_limit(diagonal, bias)
        rounded_peak = round(peak, 2)
        rounded_limit = round(limit, 2)
        results.append((rounded_peak, rounded_limit))
        results.append((diagonal, bias))
    return results


def format_rounded(index, rounded):
    return "shot {}: peak/wear {}".format(index, rounded)


def format_raw(index, raw):
    return "shot {}: raw {}".format(index, raw)


def report(label, shots):
    results = process(shots)
    lines = ["{}: {} shot(s)".format(label, len(shots))]
    index = 0
    while index < len(results):
        shot_number = index // 2
        lines.append(format_rounded(shot_number, results[index]))
        lines.append(format_raw(shot_number, results[index + 1]))
        index += 2
    return "\n".join(lines)


