import math

ALLOWED_TYPES = (list, tuple)


def _validate_point(point):
    """Return the arm length and rope twist factor of a single launch point."""
    if not isinstance(point, ALLOWED_TYPES):
        raise TypeError("each launch point must be a two-element list")
    if len(point) != 2:
        raise ValueError("a launch point holds two numbers: arm length then twist factor")
    arm, twist = point
    if twist == 0:
        raise ValueError("the rope twist factor cannot be zero")
    return float(arm), float(twist)


def _torsion_lag(arm, twist):
    """Return the remainder of the arm length divided by the twist factor."""
    return math.remainder(arm, twist)


def _frame_bias(arm, twist):
    """Return the arm length carrying the sign of the twist factor."""
    return math.copysign(arm, twist)


def calculate(launches):
    """Compute release mechanics for a list of [arm length, twist factor] points."""
    results = []
    for point in launches:
        arm, twist = _validate_point(point)
        lag = _torsion_lag(arm, twist)
        bias = _frame_bias(arm, twist)
        payload = max(lag, bias)
        stress = min(lag, bias)
        rounded_payload = round(payload, 1)
        rounded_stress = round(stress, 1)
        results.append((rounded_payload, rounded_stress))
        results.append((lag, bias))
    return results


def format_entry(entry):
    """Render one result tuple as a compact, human readable pair."""
    numbers = ["{0:.4g}".format(value) for value in entry]
    return "(" + ", ".join(numbers) + ")"


def report(label, launches):
    """Build a one line report for a named dataset of launch points."""
    rows = calculate(launches)
    pieces = [format_entry(row) for row in rows]
    body = " -> ".join(pieces)
    return "{0}: {1}".format(label, body)


if __name__ == "__main__":
    light_arm = [[50.5, 10.0]]
    heavy_arm = [[123.75, -8.5]]
    tuned_arm = [[7.0, 2.5]]
    trials = [
        ("light siege arm", light_arm),
        ("heavy counterweight arm", heavy_arm),
        ("tuned practice arm", tuned_arm),
    ]
    for label, dataset in trials:
        print(report(label, dataset))
        print(calculate(dataset))

