CELL_VOLTAGE = 3
CELL_CAPACITY = 2000
SERIES_LIMIT = 10
PARALLEL_LIMIT = 4


def parse_pack(spec):
    """Split 'series-parallel' and return the two counts as integers."""
    parts = spec.split('-')
    if len(parts) != 2:
        raise ValueError("expected 'series-parallel', got {!r}".format(spec))
    series = int(parts[0].strip())
    parallel = int(parts[1].strip())
    if series < 1 or parallel < 1:
        raise ValueError('counts must be positive in {!r}'.format(spec))
    return series, parallel


def total_voltage(series, parallel):
    """Nominal pack voltage: one cell voltage per series element."""
    return series * CELL_VOLTAGE


def total_capacity(series, parallel):
    """Nominal pack capacity in mAh: one cell capacity per parallel string."""
    return parallel * CELL_CAPACITY


def is_high_voltage(series, parallel):
    return series > SERIES_LIMIT


def is_high_capacity(series, parallel):
    return parallel > PARALLEL_LIMIT


def describe(spec, series, parallel):
    """Build a one-line human readable summary of a single pack."""
    volts = total_voltage(series, parallel)
    capacity = total_capacity(series, parallel)
    flags = []
    if is_high_voltage(series, parallel):
        flags.append('HV')
    if is_high_capacity(series, parallel):
        flags.append('HC')
    label = '+'.join(flags) or 'standard'
    return '{} -> {} V, {} mAh [{}]'.format(spec, volts, capacity, label)


def power(packs):
    """Return (capacities of high-voltage packs, voltages of high-capacity packs)."""
    hv_capacities = []
    hc_voltages = []
    for spec in packs:
        series, parallel = parse_pack(spec)
        if is_high_voltage(series, parallel):
            hv_capacities.append(total_capacity(series, parallel))
        if is_high_capacity(series, parallel):
            hc_voltages.append(total_voltage(series, parallel))
    return hv_capacities, hc_voltages


def main():
    packs = ['12-5', '4-6', '11-2', '3-3']
    for spec in packs:
        series, parallel = parse_pack(spec)
        print(describe(spec, series, parallel))
    hv_capacities, hc_voltages = power(packs)
    print('high-voltage capacities:', hv_capacities)
    print('high-capacity voltages:', hc_voltages)


if __name__ == '__main__':
    main()

