def parse_tack(tack):
    """Split a 'wind-boat' string on the hyphen and return the two integers."""
    parts = tack.split("-")
    if len(parts) != 2:
        raise ValueError("expected a 'wind-boat' pair, got {!r}".format(tack))
    return int(parts[0].strip()), int(parts[1].strip())


def apparent_wind(wind_speed, boat_speed):
    """Apparent wind felt on deck: the sum of the two speeds."""
    return wind_speed + boat_speed


def heel_angle(wind_speed, boat_speed):
    """Heel angle in degrees: one fifth of the apparent wind."""
    return apparent_wind(wind_speed, boat_speed) / 5


def is_becalmed(wind_speed, boat_speed):
    """True when there is not enough breeze to sail properly."""
    return wind_speed < 2


def is_speeding(wind_speed, boat_speed):
    """True when the hull is moving faster than ten knots."""
    return boat_speed > 10


def navigate(tacks):
    """Collect heel angles of becalmed tacks and apparent winds of fast tacks."""
    becalmed_heels = []
    speeding_winds = []
    for tack in tacks:
        wind_speed, boat_speed = parse_tack(tack)
        if is_becalmed(wind_speed, boat_speed):
            becalmed_heels.append(heel_angle(wind_speed, boat_speed))
        if is_speeding(wind_speed, boat_speed):
            speeding_winds.append(apparent_wind(wind_speed, boat_speed))
    return becalmed_heels, speeding_winds


def describe_tack(tack):
    """Build a one line human readable summary of a single tack."""
    wind_speed, boat_speed = parse_tack(tack)
    flags = []
    if is_becalmed(wind_speed, boat_speed):
        flags.append("becalmed")
    if is_speeding(wind_speed, boat_speed):
        flags.append("speeding")
    status = ", ".join(flags) if flags else "cruising"
    felt = apparent_wind(wind_speed, boat_speed)
    heel = heel_angle(wind_speed, boat_speed)
    head = "{}: apparent {} kt".format(tack, felt)
    tail = "heel {:.1f} deg ({})".format(heel, status)
    return head + ", " + tail


def format_report(tacks):
    """Return the per tack lines plus a closing summary of the two lists."""
    lines = [describe_tack(tack) for tack in tacks]
    heels, winds = navigate(tacks)
    lines.append("becalmed heels: {}".format(heels))
    lines.append("speeding apparent winds: {}".format(winds))
    return "\n".join(lines)


def main():
    log = ["1-12", "0-3"]
    log.extend(["14-18", "8-9"])
    log.append("1-4")
    print(format_report(log))
    print(navigate(["1-12"]))


if __name__ == "__main__":
    main()

