def parse_measurement(entry):
    """Split 'length-width' and return the two integers as a tuple."""
    parts = entry.split('-')
    if len(parts) != 2:
        raise ValueError("expected 'length-width', got {!r}".format(entry))
    cleaned = [part.strip() for part in parts]
    for part in cleaned:
        if not part.isdigit():
            raise ValueError('bad measurement {!r} in {!r}'.format(part, entry))
    return (int(cleaned[0]), int(cleaned[1]))


def european_size(foot_length, foot_width):
    """European size derived from the foot length."""
    return foot_length * 1.5 + 2


def width_index(foot_length, foot_width):
    """Width expressed as a percentage of the length."""
    return foot_width / foot_length * 100


def is_adult_size(foot_length, foot_width):
    """Adult sizes start above a foot length of twenty."""
    return foot_length > 20


def is_wide_fit(foot_length, foot_width):
    """A wide fit has a width index above forty."""
    return width_index(foot_length, foot_width) > 40


def measure(feet):
    """Collect adult european sizes and wide-fit width indexes."""
    adult_sizes = []
    wide_indexes = []
    for entry in feet:
        foot_length, foot_width = parse_measurement(entry)
        if is_adult_size(foot_length, foot_width):
            adult_sizes.append(european_size(foot_length, foot_width))
        if is_wide_fit(foot_length, foot_width):
            wide_indexes.append(width_index(foot_length, foot_width))
    return (adult_sizes, wide_indexes)


def describe(entry):
    """One formatted table row for a single measurement string."""
    foot_length, foot_width = parse_measurement(entry)
    flags = []
    if is_adult_size(foot_length, foot_width):
        flags.append('adult')
    if is_wide_fit(foot_length, foot_width):
        flags.append('wide')
    return '{:>7}  EU {:>5.1f}  width {:>5.1f}%  {}'.format(
        entry,
        european_size(foot_length, foot_width),
        width_index(foot_length, foot_width),
        ', '.join(flags) or 'standard',
    )


def summarize(label, values):
    """Short textual summary of a list of collected numbers."""
    if not values:
        return '{}: none collected'.format(label)
    counted = '{}: {} value(s)'.format(label, len(values))
    average = sum(values) / len(values)
    return '{}, average {:.1f}'.format(counted, average)


def main():
    samples = [
        '25-11', '18-9',
        '27-12', '22-7',
        '30-14',
    ]
    for entry in samples:
        print(describe(entry))
    adult_sizes, wide_indexes = measure(samples)
    print(summarize('Adult european sizes', adult_sizes))
    print(summarize('Wide fit indexes', wide_indexes))


if __name__ == '__main__':
    main()

