GRAVITY = 9.8
HEAVY_LIFT_MASS = 50000


def parse_stage(spec):
    if not isinstance(spec, str):
        raise TypeError("stage spec must be a string, got {!r}".format(spec))
    parts = spec.split("-")
    if len(parts) != 2:
        raise ValueError("expected 'mass-thrust', got {!r}".format(spec))
    mass = int(parts[0].strip())
    thrust = int(parts[1].strip())
    if mass <= 0:
        raise ValueError("mass must be positive in {!r}".format(spec))
    return mass, thrust


def thrust_to_weight(mass, thrust):
    return thrust / mass


def stage_acceleration(mass, thrust):
    return (thrust_to_weight(mass, thrust) - 1) * GRAVITY


def is_liftoff_capable(mass, thrust):
    return thrust_to_weight(mass, thrust) > 1


def is_heavy_lift(mass, thrust):
    return mass > HEAVY_LIFT_MASS


def launch(stages):
    accelerations = []
    heavy_ratios = []
    for spec in stages:
        mass, thrust = parse_stage(spec)
        if is_liftoff_capable(mass, thrust):
            accelerations.append(stage_acceleration(mass, thrust))
        if is_heavy_lift(mass, thrust):
            heavy_ratios.append(thrust_to_weight(mass, thrust))
    return accelerations, heavy_ratios


def format_report(stages):
    lines = []
    for spec in stages:
        mass, thrust = parse_stage(spec)
        status = "GO" if is_liftoff_capable(mass, thrust) else "NO-GO"
        klass = "heavy" if is_heavy_lift(mass, thrust) else "light"
        lines.append(
            "{:>8} kg | {:>8} N | T/W {:5.2f} | a {:6.2f} m/s^2 | {} | {}".format(
                mass,
                thrust,
                thrust_to_weight(mass, thrust),
                stage_acceleration(mass, thrust),
                status,
                klass,
            )
        )
    return "\n".join(lines)


def main():
    stages = [
        "100000-150000",
        "50000-40000",
        "2500-9000",
        "80000-240000",
    ]
    print(format_report(stages))
    accelerations, heavy_ratios = launch(stages)
    rounded_accelerations = [round(value, 2) for value in accelerations]
    rounded_ratios = [round(value, 2) for value in heavy_ratios]
    print("liftoff accelerations: {}".format(rounded_accelerations))
    print("heavy-lift T/W: {}".format(rounded_ratios))


if __name__ == "__main__":
    main()

