def average_latency(request_count, total_latency):
    if request_count <= 0:
        raise ValueError("request count must be positive: " + str(request_count))
    return total_latency / float(request_count)


def latency_gap(primary_average, secondary_average):
    return abs(primary_average - secondary_average)


def validate_node(label, node):
    if len(node) != 2:
        raise ValueError(label + " node needs a request count and a latency")
    requests = node[0]
    latency = node[1]
    if not isinstance(requests, int):
        raise TypeError(label + " request count must be an integer")
    if not isinstance(latency, int):
        raise TypeError(label + " latency must be an integer")
    if latency < 0:
        raise ValueError(label + " latency cannot be negative")


def evaluate(data):
    if len(data) != 2:
        raise ValueError("data must hold a primary node and a secondary node")
    primary, secondary = data
    validate_node("primary", primary)
    validate_node("secondary", secondary)
    primary_requests, primary_latency = primary
    secondary_requests, secondary_latency = secondary
    primary_average = average_latency(primary_requests, primary_latency)
    secondary_average = average_latency(secondary_requests, secondary_latency)
    difference = latency_gap(primary_average, secondary_average)
    return secondary_average, difference


def verdict(primary_average, secondary_average):
    tolerance = 1.0
    if latency_gap(primary_average, secondary_average) <= tolerance:
        return "nodes are balanced"
    if secondary_average < primary_average:
        return "secondary node is faster"
    return "primary node is faster"


def format_report(data):
    primary_average = average_latency(data[0][0], data[0][1])
    secondary_average, difference = evaluate(data)
    lines = [
        "primary average  : {:.2f} ms".format(primary_average),
        "secondary average: {:.2f} ms".format(secondary_average),
        "absolute gap     : {:.2f} ms".format(difference),
        "verdict          : " + verdict(primary_average, secondary_average),
    ]
    return "\n".join(lines)


def main():
    samples = [
        [
            [100, 2500],
            [80, 1600],
        ],
        [
            [50, 1000],
            [50, 1010],
        ],
    ]
    for number, sample in enumerate(samples):
        print("--- dataset {} ---".format(number + 1))
        print(format_report(sample))
    total_requests = sum(node[0] for sample in samples for node in sample)
    print("total requests observed: {}".format(total_requests))


if __name__ == "__main__":
