TOKEN_TOLERANCE = 1


def passwords_match(provided_password, expected_password):
    return provided_password == expected_password


def absolute_difference(first_number, second_number):
    return abs(first_number - second_number)


def tokens_match(provided_token, expected_token):
    drift = absolute_difference(provided_token, expected_token)
    return drift <= TOKEN_TOLERANCE


def normalise_pair(pair, label):
    sequence_types = (list, tuple)
    if not isinstance(pair, sequence_types):
        raise TypeError(label + " must be a list of password and token")
    if len(pair) != 2:
        raise ValueError(label + " needs exactly two entries")
    password, token = pair
    if not isinstance(password, str):
        raise TypeError(label + " password must be a string")
    token_is_boolean = isinstance(token, bool)
    if token_is_boolean or not isinstance(token, int):
        raise TypeError(label + " token must be an integer")
    return password, token


def authenticate(credentials):
    attempt, record = credentials
    provided = normalise_pair(attempt, "attempt")
    expected = normalise_pair(record, "record")
    provided_password, provided_token = provided
    expected_password, expected_token = expected
    password_ok = passwords_match(provided_password, expected_password)
    token_ok = tokens_match(provided_token, expected_token)
    return [password_ok, token_ok]


def describe(result):
    password_ok, token_ok = result
    if password_ok and token_ok:
        return "access granted"
    failures = []
    if not password_ok:
        failures.append("password")
    if not token_ok:
        failures.append("token")
    return "access denied: " + ", ".join(failures)


def report(credentials):
    attempt = credentials[0]
    result = authenticate(credentials)
    header = "{0} / {1}".format(attempt[0], attempt[1])
    return header + " -> " + str(result) + " (" + describe(result) + ")"


def main():
    sessions = [
        [
            ["hunter2", 4815],
            ["hunter2", 4815],
        ],
        [
            ["hunter2", 4816],
            ["hunter2", 4815],
        ],
        [
            ["Hunter2", 4815],
            ["hunter2", 4815],
        ],
        [
            ["letmein", 1000],
            ["hunter2", 1003],
        ],
    ]
    for session in sessions:
        print(report(session))


if __name__ == "__main__":
    main()

