def validate_query(query):
    if not isinstance(query, list):
        raise TypeError("query must be a list containing a word and a dictionary")
    if len(query) != 2:
        raise ValueError("query must have exactly two elements")
    word = query[0]
    dictionary = query[1]
    if not isinstance(word, str):
        raise TypeError("the target word must be a string")
    if not isinstance(dictionary, list):
        raise TypeError("the dictionary must be a list of entries")
    for entry in dictionary:
        if len(entry) != 2:
            raise ValueError("each dictionary entry must be a pair")
    return word, list(dictionary)


def find_translation(dictionary, target_word):
    for entry in dictionary:
        source_word, translated_word = entry
        if matches_ignoring_case(source_word, target_word):
            return translated_word, True
    return target_word, False


def translate(query):
    target_word, dictionary = validate_query(query)
    return find_translation(dictionary, target_word)


def format_result(target_word, result):
    translated_word, found = result
    if found:
        return "{} -> {}".format(target_word, translated_word)
    return "{} -> {} (no entry found)".format(target_word, translated_word)


def build_report(queries):
    lines = []
    for query in queries:
        target_word = query[0]
        lines.append(format_result(target_word, translate(query)))
