def duration(start, end):
    return end - start


def overlaps(first_shift, second_shift):
    first_start, first_end = first_shift
    second_start, second_end = second_shift
    return first_start < second_end and first_end > second_start


def validate_shift(shift, label):
    if len(shift) != 2:
        raise ValueError(f"{label} must hold a start hour and an end hour")
    start, end = shift
    for hour in shift:
        if not isinstance(hour, int):
            raise TypeError(f"{label} hours must be integers, got {hour!r}")
    if not 0 <= start <= 24:
        raise ValueError(f"{label} start hour {start} is outside 0..24")
    if not 0 <= end <= 24:
        raise ValueError(f"{label} end hour {end} is outside 0..24")
    if start >= end:
        raise ValueError(f"{label} must start before it ends: {start} >= {end}")


def format_shift(start, end):
    return f"{start:02d}:00-{end:02d}:00"


def coverage(shifts):
    if len(shifts) != 2:
        raise ValueError("coverage expects exactly two shift lists")
    first_shift, second_shift = shifts
    validate_shift(first_shift, "first shift")
    validate_shift(second_shift, "second shift")
    start, end = first_shift
    total = duration(start, end)
    overlapping = overlaps(first_shift, second_shift)
    return total, overlapping


def report(shifts):
    total, overlapping = coverage(shifts)
    first_shift, second_shift = shifts
    first_label = format_shift(first_shift[0], first_shift[1])
    second_label = format_shift(second_shift[0], second_shift[1])
    status = "overlap" if overlapping else "no overlap"
    return f"{first_label} vs {second_label}: {total}h logged, {status}"


def main():
    morning = [9, 17]
    afternoon = [13, 21]
    night = [22, 24]
    early = [6, 14]
    split = [8, 12]
    late = [12, 20]
    rosters = [
        [morning, afternoon],
        [night, early],
        [split, late],
        [early, morning],
    ]
    for shifts in rosters:
        print(report(shifts))


if __name__ == "__main__":
    main()

