def reverse_string(s):
    """Return the characters of s in reverse order."""
    if not isinstance(s, str):
        raise TypeError("reverse_string expects a str, not " + type(s).__name__)
    return s[::-1]


def reverse_words(sentence, sep=" "):
    """Reverse the order of the words in sentence, keeping each word intact."""
    words = sentence.split(sep)
    return sep.join(reversed(words))


def reverse_each_word(sentence, sep=" "):
    """Reverse the letters inside every word but keep the word order."""
    words = sentence.split(sep)
    return sep.join(reverse_string(word) for word in words)


def normalise(s):
    """Fold case and drop every character that is not alphanumeric."""
    return "".join(ch.lower() for ch in s if ch.isalnum())


def is_palindrome(s):
    """True when s reads the same both ways, ignoring case and punctuation."""
    cleaned = normalise(s)
    return cleaned == reverse_string(cleaned)


def describe(s):
    """Return the reversed form of s together with its palindrome verdict."""
    flag = "yes" if is_palindrome(s) else "no"
    return reverse_string(s), flag


def format_row(original, width):
    """Build one aligned line of the report table."""
    flipped, flag = describe(original)
    cells = [original.ljust(width), flipped.ljust(width)]
    return " ".join(cells) + " " + flag.rjust(4)


def build_report(samples):
    """Produce the report lines for a sequence of sample strings."""
    width = max((len(sample) for sample in samples), default=0)
    width = max(width, len("reversed"))
    heading = "original".ljust(width) + " " + "reversed".ljust(width) + " pal?"
    lines = [heading, "-" * len(heading)]
    for sample in samples:
        lines.append(format_row(sample, width))
    return lines


