import sys

COLUMN_WIDTH = 8
COUNT_KEYS = 'lines words chars'.split()


def count_lines_in_file(filepath):
    """Return the number of lines in the file at filepath."""
    with open(filepath, encoding='utf-8') as handle:
        return sum(1 for _ in handle)


def count_words_in_file(filepath):
    """Return how many blank-separated tokens the file holds."""
    total = 0
    with open(filepath, encoding='utf-8') as handle:
        for line in handle:
            total += len(line.split())
    return total


def count_chars_in_file(filepath):
    """Return the number of characters in the file."""
    with open(filepath, encoding='utf-8') as handle:
        return sum(len(line) for line in handle)


def file_stats(filepath):
    """Return the path of one file together with its three counts."""
    return {
        'path': filepath,
        'lines': count_lines_in_file(filepath),
        'words': count_words_in_file(filepath),
        'chars': count_chars_in_file(filepath),
    }


def format_row(stats, width=COLUMN_WIDTH):
    """Format one record as a row of right-aligned counts."""
    cells = [str(stats[key]).rjust(width) for key in COUNT_KEYS]
    cells.append(stats['path'])
    return '  '.join(cells)


def format_report(records):
    """Build a header line, one row per file and a total row."""
    titles = [key.rjust(COLUMN_WIDTH) for key in COUNT_KEYS]
    titles.append('path')
    rows = ['  '.join(titles)]
    for record in records:
        rows.append(format_row(record))
    if len(records) > 1:
        totals = {'path': 'total'}
        for key in COUNT_KEYS:
            totals[key] = sum(record[key] for record in records)
        rows.append(format_row(totals))
    return '\n'.join(rows)


def main(argv):
    paths = argv[1:]
    if not paths:
        print('usage: wordcount.py FILE [FILE ...]', file=sys.stderr)
        return 2
    records = []
    for path in paths:
        try:
            records.append(file_stats(path))
        except OSError as exc:
            message = '%s: %s' % (path, exc)
            print(message, file=sys.stderr)
            return 1
    print(format_report(records))
    return 0


if __name__ == '__main__':
    raise SystemExit(main(sys.argv))

