import sys


def _validate(n):
    """Raise if n is not a usable count of squares."""
    if isinstance(n, bool):
        raise TypeError("booleans are not accepted as a count")
    if not isinstance(n, int):
        raise TypeError("n must be an int, got " + type(n).__name__)
    if n < 0:
        raise ValueError("n must be non-negative, got {}".format(n))


def list_of_squares(n):
    """Return the squares of the integers from 1 to n inclusive."""
    _validate(n)
    return [i * i for i in range(1, n + 1)]


def squares_summary(squares):
    """Collect a few descriptive numbers about a list of squares."""
    return {
        "count": len(squares),
        "total": sum(squares),
        "smallest": min(squares, default=0),
        "largest": max(squares, default=0),
    }


def format_table(squares):
    """Render the squares as an aligned two-column text table."""
    rows = ["{:>5} {:>9}".format("i", "i * i")]
    rows.append("{:>5} {:>9}".format("-" * 5, "-" * 9))
    for index in range(1, len(squares) + 1):
        rows.append("{:>5} {:>9}".format(index, squares[index - 1]))
    return "\n".join(rows)


def format_summary(summary):
    """Render a summary mapping as a single readable line."""
    parts = []
    for key in sorted(summary):
        parts.append("{}={}".format(key, summary[key]))
    return ", ".join(parts)


def format_inline(squares, limit=6):
    """Render the squares on one line, truncating long sequences."""
    shown = [str(square) for square in squares[:limit]]
    if len(squares) > limit:
        shown.append("... (+{} more)".format(len(squares) - limit))
    return "[{}]".format(", ".join(shown))


def report(n):
    """Build a full report for list_of_squares(n)."""
    squares = list_of_squares(n)
    parts = [
        "n = {}".format(n),
        format_inline(squares),
        format_summary(squares_summary(squares)),
    ]
    if squares:
        parts.append(format_table(squares))
    return "\n".join(parts)


def main(argv):
    if len(argv) != 2:
        print("usage: {} N".format(argv[0]))
        return 2
    try:
        n = int(argv[1])
    except ValueError:
        print("N must be an integer, got " + repr(argv[1]))
        return 2
    try:
        print(report(n))
    except ValueError as error:
        print("error: {}".format(error))
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

