def sort_dict_by_value(d):
    """Return the items of ``d`` as a list of tuples sorted by value ascending."""
    if not isinstance(d, dict):
        raise TypeError("sort_dict_by_value expects a dict, got %r" % type(d).__name__)
    return sorted(d.items(), key=lambda item: item[1])


def sort_dict_by_value_desc(d):
    """Same ordering criterion, but from the largest value down to the smallest."""
    return list(reversed(sort_dict_by_value(d)))


def top_n(d, n):
    """Return the ``n`` largest entries of ``d``, ties broken by insertion order."""
    if n < 0:
        raise ValueError("n must be non-negative")
    return sort_dict_by_value_desc(d)[:n]


def value_span(d):
    """Return a (minimum, maximum) pair of values, or None for an empty mapping."""
    ordered = sort_dict_by_value(d)
    if not ordered:
        return None
    return ordered[0][1], ordered[-1][1]


def merge_counts(*mappings):
    """Add up several name -> number mappings into a single dictionary."""
    totals = {}
    for mapping in mappings:
        for key, value in mapping.items():
            totals[key] = totals.get(key, 0) + value
    return totals


def format_report(d, title):
    """Render a mapping as a small aligned table, smallest value first."""
    ordered = sort_dict_by_value(d)
    if not ordered:
        return "%s\n  (empty)" % title
    width = max(len(str(key)) for key, _ in ordered)
    lines = [title]
    for key, value in ordered:
        lines.append("  %s %s" % (str(key).ljust(width), value))
    low, high = value_span(d)
    lines.append("  range: %s .. %s" % (low, high))
    return "\n".join(lines)


def main():
    scores = {
        'a': 3, 'b': 1,
        'c': 2,
    }
    print(sort_dict_by_value(scores))
    print(sort_dict_by_value({}))

    monday = {
        'apples': 4, 'pears': 9,
        'plums': 2,
    }
    tuesday = {
        'apples': 5, 'cherries': 7,
        'pears': 1,
    }
    stock = merge_counts(monday, tuesday)
    print(format_report(stock, "Fruit stock"))
    busiest = top_n(stock, 2)
    print("top two:", busiest)

    durations = {
        'boot': 1.75, 'render': 0.4,
        'fetch': 2.5, 'parse': 0.9,
    }
    print(format_report(durations, "Stage durations (s)"))
    slowest = sort_dict_by_value_desc(durations)[0]
    print("slowest:", slowest)
    fastest = [name for name, _ in sort_dict_by_value(durations)[:3]]
    print("fastest three:", fastest)


if __name__ == "__main__":
    main()

