import random
from collections import Counter


def roll_dice(num_dice, sides):
    """Roll `num_dice` dice with `sides` faces each and return the outcomes."""
    validate_roll(num_dice, sides)
    return [random.randint(1, sides) for _ in range(num_dice)]


def validate_roll(num_dice, sides):
    """Reject rolls that cannot be simulated with integral dice."""
    labelled = [
        ("num_dice", num_dice),
        ("sides", sides),
    ]
    for name, value in labelled:
        if not isinstance(value, int):
            raise TypeError("{} must be an integer".format(name))
    if num_dice < 1:
        raise ValueError("num_dice must be at least 1")
    if sides < 2:
        raise ValueError("sides must be at least 2")


def tally(rolls, sides):
    """Count how often each face appeared, including faces never rolled."""
    counts = Counter(rolls)
    faces = range(1, sides + 1)
    return [(face, counts[face]) for face in faces]


def histogram(rolls, sides):
    """Render the face frequencies as aligned rows of marks."""
    width = len(str(sides))
    counted = tally(rolls, sides)
    lines = []
    for face, count in counted:
        label = "{:>{w}}".format(face, w=width)
        lines.append(label + " | " + "#" * count)
    return "\n".join(lines)


def notation(spec):
    """Format a (num_dice, sides) pair in dice notation."""
    num_dice, sides = spec
    return "{}d{}".format(num_dice, sides)


def report(label, spec):
