from datetime import datetime

COLUMNS = [
    ('event', 'Event'),
    ('date', 'Date'),
    ('days', 'Days'),
    ('relative', 'Relative'),
]


def parse_date(text, label):
    try:
        return datetime.strptime(text.strip(), '%Y-%m-%d').date()
    except ValueError:
        raise ValueError('%s is not a valid YYYY-MM-DD date: %r' % (label, text))


def days_remaining(start_date_str, end_date_str):
    start = parse_date(start_date_str, 'start_date_str')
    end = parse_date(end_date_str, 'end_date_str')
    return (end - start).days


def describe_gap(start_date_str, end_date_str):
    days = days_remaining(start_date_str, end_date_str)
    if days == 0:
        return 'today'
    weeks = abs(days) // 7
    extra = abs(days) % 7
    parts = []
    if weeks:
        parts.append('%d week%s' % (weeks, '' if weeks == 1 else 's'))
    if extra:
        parts.append('%d day%s' % (extra, '' if extra == 1 else 's'))
    phrase = ' and '.join(parts)
    return '%s ago' % phrase if days < 0 else 'in %s' % phrase


def countdown_rows(start_date_str, events):
    rows = []
    for name, target in events:
        row = {'event': name, 'date': target}
        row['days'] = days_remaining(start_date_str, target)
        row['relative'] = describe_gap(start_date_str, target)
        rows.append(row)
    rows.sort(key=lambda row: row['days'])
    return rows


def format_row(cells, widths):
    parts = []
    for index in range(len(cells)):
        parts.append(cells[index].ljust(widths[index]))
    return '  '.join(parts).rstrip()


def format_table(rows):
    widths = []
    for column in COLUMNS:
        cells = [column[1]] + [str(row[column[0]]) for row in rows]
        widths.append(max(len(cell) for cell in cells))
    lines = [format_row([column[1] for column in COLUMNS], widths)]
    for row in rows:
        cells = [str(row[column[0]]) for column in COLUMNS]
        lines.append(format_row(cells, widths))
    return '\n'.join(lines)


def main():
    print(days_remaining('2023-01-01', '2023-01-05'))
    print(days_remaining('2023-12-31', '2024-01-01'))
    events = [
        ('New Year 2024', '2024-01-01'),
        ('Leap Day 2024', '2024-02-29'),
        ('New Year 2025', '2025-01-01'),
    ]
    print(format_table(countdown_rows('2023-12-31', events)))


if __name__ == '__main__':
    main()

