NUM_WIDTH = 6
CUBE_WIDTH = 14

SAMPLE_LIMITS = [
    "3",
    "0",
    "6",
]


def cubes_up_to(limit):
    """Return the cubes of every integer from 0 up to the limit inclusive."""
    validate_limit(limit)
    cubes_list = [n ** 3 for n in range(0, limit + 1)]
    return cubes_list


def validate_limit(limit):
    """Reject anything that is not a usable non-negative integer limit."""
    if not isinstance(limit, int):
        raise TypeError("limit must be an int: {!r}".format(limit))
    if limit < 0:
        raise ValueError("limit must be non-negative: {}".format(limit))


def parse_limit(text):
    """Turn a textual limit (as typed on a command line) into an int."""
    stripped = text.strip()
    if not stripped.isdigit():
        raise ValueError("cannot read a limit from {!r}".format(text))
    return int(stripped)


def cube_table(limit):
    """Pair each number with its cube, ready for tabular output."""
    return list(zip(range(limit + 1), cubes_up_to(limit)))


def format_row(number, cube):
    """Render one number/cube pair as an aligned text line."""
    left = "{:>{}}".format(number, NUM_WIDTH)
    right = "{:>{}}".format(cube, CUBE_WIDTH)
    return left + right


def format_table(limit):
    """Render the whole number/cube table with a header."""
    lines = [format_row("n", "n**3")]
    lines.append("-" * (NUM_WIDTH + CUBE_WIDTH))
    for number, cube in cube_table(limit):
        lines.append(format_row(number, cube))
    return "\n".join(lines)


def summarize(limit):
    """Collect a few useful facts about the cubes up to the limit."""
    cubes = cubes_up_to(limit)
    return {
        "count": len(cubes),
        "total": sum(cubes),
        "largest": cubes[-1],
        "even": [c for c in cubes if c % 2 == 0],
    }


def format_summary(limit):
    """Render the summary figures as a single readable line."""
    facts = summarize(limit)
    parts = [
        "count={count}".format(**facts),
        "total={total}".format(**facts),
        "largest={largest}".format(**facts),
        "even={even}".format(**facts),
    ]
    return " | ".join(parts)


def main():
    for text in SAMPLE_LIMITS:
        limit = parse_limit(text)
        print("cubes_up_to({}) -> {}".format(limit, cubes_up_to(limit)))
    print()
    print(format_table(6))
    print()
    print(format_summary(6))


if __name__ == "__main__":
    main()

