"""Grayscale conversion of small RGB images supplied in textual form."""

SAMPLES = [
    ("red and green", "255,0,0 0,255,0"),
    ("single pixel", "10,20,30"),
    ("gradient", "0,0,0 64,64,64\n128,128,128 255,255,255"),
]


def validate_pixel(pixel):
    """Check that a pixel holds exactly three channel values in 0..255."""
    if not isinstance(pixel, list) or len(pixel) != 3:
        raise ValueError("each pixel must hold three channel values")
    for channel in pixel:
        if type(channel) is not int:
            raise TypeError("channel values must be integers")
        if not 0 <= channel <= 255:
            raise ValueError("channel values must lie in 0..255")


def parse_pixel(token):
    """Turn an 'R,G,B' token into a validated list of channel values."""
    channels = [int(part) for part in token.split(",")]
    validate_pixel(channels)
    return channels


def parse_image(text):
    """Build an image matrix from one text line of pixel tokens per row."""
    return [[parse_pixel(token) for token in row_text.split()]
            for row_text in text.strip().splitlines()]


def to_grayscale(image_matrix):
    """Convert an RGB image matrix into a matrix of grayscale intensities."""
    grayscale_image = []
    for row in image_matrix:
        for pixel in row:
            validate_pixel(pixel)
        grayscale_image.append([sum(pixel) // 3 for pixel in row])
    return grayscale_image


def image_stats(grayscale_image):
    """Summarise the size and the intensity range of a grayscale image."""
    values = [value for row in grayscale_image for value in row]
    if not values:
        raise ValueError("cannot summarise an empty image")
    stats = {}
    stats["width"] = len(grayscale_image[0])
    stats["height"] = len(grayscale_image)
    stats["min"] = min(values)
    stats["max"] = max(values)
    stats["mean"] = sum(values) / len(values)
    return stats


def render_ascii(grayscale_image, ramp=" .:-=+*#%@"):
    """Render the grayscale image as ASCII art using the given ramp."""
    last = len(ramp) - 1
    return "\n".join("".join(ramp[value * last // 255] for value in row)
                     for row in grayscale_image)


def describe(name, text):
    """Print the grayscale pixels, the statistics and the art of an image."""
    gray = to_grayscale(parse_image(text))
    stats = image_stats(gray)
    print("{0}: {1}".format(name, gray))
    print("  {width}x{height} {min}-{max} mean {mean:.2f}".format(**stats))
    print(render_ascii(gray))


def main():
    for name, text in SAMPLES:
        describe(name, text)


if __name__ == "__main__":
    main()

