        raise TypeError("hex_string must be a str, got %s" % type(hex_string).__name__)
    digits = strip_prefix(hex_string).replace("_","").upper()
    if not digits:
        raise ValueError("hex_string contains no hexadecimal digits")
    for position,digit in enumerate(digits):
        if digit not in HEX_DIGITS:
            message = "bad digit %r at index %d" % (digit,position)
            raise ValueError("%s in %r" % (message,hex_string))
    return digits


def hex_to_decimal(hex_string):
    """Convert a hexadecimal string to its decimal integer equivalent."""
    digits = validate(hex_string)
    total = 0
    for digit in digits:
        total = total * 16 + HEX_DIGITS.index(digit)
    return total


def decimal_to_hex(value,width=1):
    """Render a non-negative integer back into upper-case hexadecimal."""
    if value < 0:
        raise ValueError("value must be non-negative")
    out = []
    while value:
        out.append(HEX_DIGITS[value % 16])
        value //= 16
    while len(out) < width:
        out.append("0")
    return "".join(reversed(out))


def describe(hex_string):
    """Build a one-line report about a hexadecimal literal."""
    digits = validate(hex_string)
    value = hex_to_decimal(digits)
    parts = [
        "input=%s" % hex_string,
        "digits=%s" % digits,
        "decimal=%d" % value,
        "roundtrip=%s" % decimal_to_hex(value,len(digits)),
        "bits=%d" % value.bit_length(),
    ]
    return " | ".join(parts)


def main():
    samples = [
        "A","1A",
        "0xff",
        "#DEAD_BEEF",
        "0","7fffffff",
    ]
    for sample in samples:
        print(describe(sample))
    broken = [
        "","12G4",
        "0x",
    ]
    for sample in broken:
        try:
            hex_to_decimal(sample)
        except ValueError as error:
            print("rejected %r: %s" % (sample,error))
    print("sum of samples =",sum(hex_to_decimal(item) for item in samples))


if __name__ == "__main__":
    main()

