class Queue:
    """A simple FIFO queue backed by a Python list."""

    def __init__(self, items=None):
        self._items = list(items) if items is not None else []

    def enqueue(self, item):
        self._items.append(item)
        return item

    def dequeue(self):
        if not self._items:
            return None
        return self._items.pop(0)

    def peek(self):
        if not self._items:
            return None
        return self._items[0]

    def to_list(self):
        return list(self._items)

    def __len__(self):
        return len(self._items)

    def __repr__(self):
        inside = ", ".join(repr(item) for item in self._items)
        return "Queue([{}])".format(inside)


def fill(queue, items):
    for item in items:
        queue.enqueue(item)
    return queue


def drain(queue, count):
    removed = []
    while len(removed) < count:
        removed.append(queue.dequeue())
    return removed


def serve_tickets(names, window_count):
    """Distribute names round-robin over the given number of service windows."""
    if window_count < 1:
        raise ValueError("window_count must be at least 1")
    line = fill(Queue(), names)
    windows = [Queue() for _ in range(window_count)]
    index = 0
    while len(line):
        windows[index % window_count].enqueue(line.dequeue())
        index += 1
    return [window.to_list() for window in windows]


def format_report(assignments):
    lines = []
    for index, names in enumerate(assignments):
        served = ", ".join(names) if names else "(idle)"
        lines.append("Window {}: {}".format(index + 1, served))
    return "\n".join(lines)


def main():
    numbers = range(1, 5)
    q = fill(Queue(), numbers)
    print("queue:", q)
    print("front:", q.peek())
    first_two = drain(q, 2)
    print("first two out:", first_two)
    print("remaining size:", len(q))
    print("empty dequeue:", Queue().dequeue())
    customers = "Ada Linus Grace Alan Edsger".split()
    assignments = serve_tickets(customers, 3)
    print(format_report(assignments))


if __name__ == "__main__":
    main()

