"""Parse URL query strings into dictionaries of key-value pairs."""

PREFIX_CHARS = "?#"
PAIR_SEPARATOR = "&"
VALUE_SEPARATOR = "="


def split_pairs(query_string):
    """Split a query string into its non-empty 'key=value' chunks."""
    cleaned = query_string.strip().lstrip(PREFIX_CHARS)
    return [chunk for chunk in cleaned.split(PAIR_SEPARATOR) if chunk]


def split_pair(pair):
    """Split one chunk into a (key, value) tuple; a missing '=' means empty value."""
    parts = pair.split(VALUE_SEPARATOR, 1)
    key = parts[0].strip()
    if len(parts) == 1:
        value = ""
    else:
        value = parts[1].strip()
    return key, value


def parse_url_params(query_string):
    """Return a dict of the parameters found in query_string."""
    params = {}
    for pair in split_pairs(query_string):
        key, value = split_pair(pair)
        if key:
            params[key] = value
    return params


def build_query(params):
    """Rebuild a canonical query string from a parameter dict."""
    parts = []
    for key, value in sorted(params.items()):
        parts.append(key + VALUE_SEPARATOR + value)
    return PAIR_SEPARATOR.join(parts)


def format_params(params):
    """Render the parameters as an aligned, human readable block."""
    if not params:
        return "(no parameters)"
    width = max(len(key) for key in params)
    lines = []
    for key, value in sorted(params.items()):
        label = key.ljust(width)
        lines.append("{} = {!r}".format(label, value))
    return "\n".join(lines)


def main():
    samples = [
        "name=John&age=30",
        "q=python+programming",
        "?a=1&b=2&flag",
        "",
    ]
    for sample in samples:
        params = parse_url_params(sample)
        print("query   : {!r}".format(sample))
        print(format_params(params))
        print("rebuilt : {}".format(build_query(params)))
        print("name    : {}".format(params.get("name", "<missing>")))
        print("count   : {}".format(len(params)))
        print()


if __name__ == "__main__":
    main()

