def is_prime(number):
    """Return True when `number` is a prime, using trial division."""
    if number < 2:
        return False
    if number in (2,3):
        return True
    if number % 2 == 0:
        return False
    divisor = 3
    while divisor * divisor <= number:
        if number % divisor == 0:
            return False
        divisor += 2
    return True


def generate_primes(n):
    """Return every prime up to and including `n`."""
    if isinstance(n,bool):
        raise TypeError("n must be a plain integer")
    if not isinstance(n,int):
        raise TypeError("n must be an integer")
    return [candidate for candidate in range(2,n + 1) if is_prime(candidate)]


def twin_pairs(primes):
