def validate_inputs(string_list, min_length):
    """Check the arguments and return the strings as a fresh list."""
    sequence_types = (list, tuple)
    if not isinstance(string_list, sequence_types):
        raise TypeError("string_list must be a list of strings")
    if isinstance(min_length, bool):
        raise TypeError("min_length must be an integer, not a boolean")
    if not isinstance(min_length, int):
        raise TypeError("min_length must be an integer")
    if min_length < 0:
        raise ValueError("min_length must be non-negative")
    for item in string_list:
        if not isinstance(item, str):
            raise TypeError("every element of string_list must be a str")
    return list(string_list)


def filter_by_length(string_list, min_length):
    """Return the strings from string_list longer than min_length."""
    items = validate_inputs(string_list, min_length)
    return [text for text in items if len(text) > min_length]


def partition_by_length(string_list, min_length):
    """Split the input into (kept, dropped) according to the length rule."""
    items = validate_inputs(string_list, min_length)
    kept = []
    dropped = []
    for text in items:
        if len(text) > min_length:
            kept.append(text)
        else:
            dropped.append(text)
    return kept, dropped


def length_table(string_list):
    """Map each distinct string to its length, preserving first appearance."""
    table = {}
    for text in string_list:
        table.setdefault(text, len(text))
    return table


def format_report(string_list, min_length):
    """Build a human readable summary of one filtering operation."""
    parts = partition_by_length(string_list, min_length)
    kept, dropped = parts
    sizes = length_table(string_list)
    pairs = []
    for text in sizes:
        pairs.append("{}:{}".format(text, sizes[text]))
    lines = [
        "min_length = {}".format(min_length),
        "input      = {}".format(", ".join(string_list) or "(empty)"),
        "lengths    = {}".format(" ".join(pairs) or "(empty)"),
        "kept       = {}".format(kept),
        "dropped    = {}".format(dropped),
    ]
    return "\n".join(lines)


