def enqueue(queue, item):
    """Append item to the end of the queue."""
    queue.append(item)


def dequeue(queue):
    """Remove and return the first item, or None when the queue is empty."""
    if not queue:
        return None
    return queue.pop(0)


def peek(queue):
    """Return the next item without removing it, or None when empty."""
    if not queue:
        return None
    return queue[0]


def enqueue_all(queue, items):
    """Enqueue every item of an iterable, in order."""
    for item in items:
        enqueue(queue, item)


def drain(queue, count=None):
    """Dequeue up to count items (all of them when count is None)."""
    served = []
    limit = len(queue) if count is None else min(count, len(queue))
    for _ in range(limit):
        served.append(dequeue(queue))
    return served


def join_items(items):
    """Render items as a comma-separated list."""
    return ", ".join(str(item) for item in items)


def format_queue(queue):
    """Render the queue as an arrow-separated waiting line."""
    if not queue:
        return "<empty>"
    return " -> ".join(str(item) for item in queue)


def simulate(rounds, capacity=2):
    """Serve then admit arrivals each round, returning a report line per round."""
    queue = []
    report = []
    number = 0
    for arrivals in rounds:
        number += 1
        served = drain(queue, capacity)
        enqueue_all(queue, arrivals)
        parts = ["round %d" % number]
        parts.append("served [%s]" % join_items(served))
        parts.append("waiting %s" % format_queue(queue))
        parts.append("next %s" % peek(queue))
        report.append(", ".join(parts))
    leftovers = drain(queue)
    report.append("closing: served [%s]" % join_items(leftovers))
    return report


def main():
    rounds = [
        ["ann", "bob"],
        ["cid"],
        [],
        ["dee", "eve"],
        ["fay", "gus"],
    ]
    for line in simulate(rounds, capacity=2):
        print(line)


if __name__ == "__main__":
    main()

